template <typename BE, typename PR>
struct MeshCubeInitializer : GeneralMeshInitializer<BE, PR> {
    using ParamsType = MeshCubeInitializerParams<PR>;
    ParamsType params;

    MeshCubeInitializer(ParamsType params) : params(params) {}

    void initialize(MeshState<BE, PR>& state, MeshAdjacency<BE, PR>& adjacency) override {
        state.memoryAllocation(params);
        adjacency.memoryAllocation(params);

        auto geom = primitive::cube(
            (float)params.size, (int)params.tessellation,
            {params.center.x, params.center.y, params.center.z});

        for (Index v = 0; v < params.numPoints; ++v) {
            Index vbase = v * 3;
            state.x[vbase    ] = (PR)geom.positions[vbase    ];
            state.x[vbase + 1] = (PR)geom.positions[vbase + 1];
            state.x[vbase + 2] = (PR)geom.positions[vbase + 2];
        }

        if (adjacency.vertexAdjFacets.ptr) return;
        for (Index f = 0; f < params.numFacets; ++f) {
            Index fbase = f * 3;
            adjacency.facets[fbase    ] = geom.facets[fbase    ];
            adjacency.facets[fbase + 1] = geom.facets[fbase + 1];
            adjacency.facets[fbase + 2] = geom.facets[fbase + 2];
        }

        MeshAdjacencyInitializer<BE, PR>::initialize(state, adjacency);
    }

    void populatePreview(PreviewState<PR>& preview) override {
        auto geom = primitive::cube(
            (float)params.size, (int)params.tessellation,
            {params.center.x, params.center.y, params.center.z});
        // Physics buffers: welded single-manifold (cloth springs cross seams).
        preview.x.assign(geom.positions.begin(), geom.positions.end());
        preview.facets.assign(geom.facets.begin(), geom.facets.end());
        preview.recomputeNormals();
        // 2026-05-15 (A2 split): render buffers carry the unwelded per-face
        // copies so MeshGL renders flat per-face normals (crisp cube edges).
        // primitive::cube guarantees these are populated when called for the
        // cube primitive; copying through PR (preview is template-PR) handles
        // the float→double case for future CPU-double scenes.
        preview.renderX.assign(geom.renderPositions.begin(), geom.renderPositions.end());
        preview.renderFacets.assign(geom.renderFacets.begin(), geom.renderFacets.end());
        preview.renderN.assign(geom.renderNormals.begin(), geom.renderNormals.end());
        preview.renderToPhysics.assign(geom.renderToPhysics.begin(),
                                       geom.renderToPhysics.end());
    }

    InitializerParams<PR>* getParams() override { return &params; }
};


struct alignas(8) IndexPair {
    union {
        struct { Index query, target; }; 
        struct { Index point, triangle; }; 
        struct { Index edge1, edge2; };
    };

    bool operator<(const IndexPair& o) const {
        if(query == o.query) return target < o.target;
        return query < o.query;
    }
};

// Per-mesh collision geometry class. Mirrored into the GPU
// `meshShapes` buffer (Scene::pack → MetalGlobalContext slot 10) as
// the raw enum value, so the numeric order is GPU-visible — APPEND
// new entries, never renumber existing ones. Assigned in Scene::pack
// from the request's initializer subtype (the same dynamic_cast
// cascade that seeds transformPosition).
//
// Sphere/Cube/Cylinder are analytic primitives: a future slice (c)
// keys an analytic broad/narrow path on these so they skip the
// BVH/SH mesh pipeline. Until then this is classification metadata
// only — no collision code branches on it yet, so assigning it is
// behaviorally inert (safe to land independently).
enum struct ShapeType : Index {
    Mesh,     // general triangle soup — per-particle/triangle collision
    Plane,    // reserved analytic plane (not yet auto-assigned; see (c))
    Sphere,
    Cube,
    Cylinder,
};

// Picking mode. Object: id-buffer triangle pass → whole-mesh hover/
// select + outline. Point: id-buffer GL_POINTS pass → per-vertex
// hover/select with on-screen dots. Exactly one off-screen id pass
// runs per frame, branched on this (requirement 3).
enum struct SelectionMode : int {
    Object,
    Point,
};

// A pinned vertex constraint. `vid` is the PHYSICS vertex index within
// its mesh (constraints.fixedParticles[vid] = 0). `pos` is the world
// position the vertex is held at. Stored on RequestGeneralMesh (so it
// survives Scene::pack — like applyGravity/rotationQuat mirrors) and
// round-tripped through scene_format as a per-object constraint list.
struct FixedVertex {
    uint32_t vid;
    tinym::vec3 pos;
};

// A reference-point coincidence constraint (point-selection panel).
// Expressed via IndexPair per the design: the vertex `vertexPair.query`
// of the object whose id is `objPair.query` (the FOLLOWER) must track the
// position of vertex `vertexPair.target` of the object `objPair.target`
// (the LEADER) every integration step. `.query`/`.target` of vertexPair
// are PHYSICS vertex ids (same space as FixedVertex::vid). Stored in a
// Scene-static list that survives Scene::pack/reset and round-trips
// through scene_format.
struct ReferencePointConstraint {
    IndexPair objPair;
    IndexPair vertexPair;
};

const char* behaviorTypeName(BehaviorType behaviorType) {
    switch (behaviorType) {
        case BehaviorType::TriangularCloth: return "TriangularCloth";
        case BehaviorType::FastGridCloth: return "FastGridCloth";
        case BehaviorType::Elastic: return "Elastic";
        case BehaviorType::Rigid: return "Rigid";
        case BehaviorType::Float: return "Float";
        case BehaviorType::Fluid: return "Fluid";
        case BehaviorType::Generator: return "Generator";
        case BehaviorType::Kinematic: return "Kinematic";
        default: return "Unknown";
    }
}

// BVH motion asset directory — external asset, referenced from the project
// source tree (no longer copied into the build). ysim_paths::assetFile
// honors the YSIM_ASSET_ROOT / project-root resolution.
inline std::string bvhAssetDir() {
    return ysim_paths::assetFile("BVH");
}

// Sorted *.bvh file names (no directory) in bvhAssetDir().
inline std::vector<std::string> listBVHFiles() {
    namespace fs = std::filesystem;
    std::vector<std::string> out;
    std::error_code ec;
    for (const auto& e : fs::directory_iterator(bvhAssetDir(), ec)) {
        if (!e.is_regular_file()) continue;
        if (e.path().extension() != ".bvh") continue;
        out.push_back(e.path().filename().string());
    }
    std::sort(out.begin(), out.end());
    return out;
}

const char* shapeTypeName(ShapeType shapeType) {
    switch (shapeType) {
        case ShapeType::Mesh: return "Mesh";
        case ShapeType::Plane: return "Plane";
        case ShapeType::Sphere: return "Sphere";
        case ShapeType::Cube: return "Cube";
        case ShapeType::Cylinder: return "Cylinder";
        default: return "Unknown";
    }
}

struct alignas(32) BroadCollision {
    IndexPair indexPair;
    IndexPair objPair;
    IndexPair behaviorPair;
    IndexPair shapePair;
};

// Cluster-pair broad phase (cluster VF pipeline) — MUST match bvh.metal layout.
struct ClusterPair { uint32_t a; uint32_t b; };   // (query cluster, target cluster)
struct ClusterGridParams {
    float ox, oy, oz;     // grid origin (min corner)
    float cellSize;       // uniform cell size (~ max cluster extent)
    int   dx, dy, dz;     // grid dims
    uint32_t numQuery;    // # query clusters
    uint32_t maxPairs;    // pair buffer capacity
    float margin;         // inflate query AABBs (VF needs margin-expanded pairs)
};

struct NarrowCollision {
    IndexPair indexPair;
    IndexPair objPair;
    tinym::vec4 collisionNormalAndDistance;
    IndexPair behaviorPair;
    IndexPair shapePair;
};

// Slice (c) — per-primitive analytic collision descriptor. COMPACT
// array (count = #primitive-shaped meshes, NOT numMeshes; A4): each
// entry self-describes via objId. Allocated at Scene::pack, contents
// refilled from the live mesh transform each frame (D3). GPU-visible;
// vec4-packed so the future analytic narrow kernel reads it without
// padding surprises. INERT in c-0 — allocated + filled, no consumer
// kernel yet (c-1 adds it). `prevCenterPad` is reserved for the c-4
// swept-CCD / Bullet-motion path; v1 is DCD (Q2) so it stays unused.
struct alignas(16) AnalyticShape {
    tinym::vec4 centerRadius;   // xyz = world center, w = radius (sphere/cyl)
    tinym::vec4 halfExtHeight;  // xyz = OBB half-extents (cube), w = cyl half-height
    tinym::vec4 rotQuat;        // world orientation (w,x,y,z) for OBB cube/cyl
    tinym::vec4 prevCenterPad;  // xyz = prev center (reserved c-4 CCD); w = pad
    uint32_t shapeType;         // ShapeType enum value
    uint32_t objId;             // owning mesh id (debug / NarrowCollision.objPair)
    uint32_t behaviorType;      // BehaviorType (cloth-vs-prim gate / future prim-prim)
    uint32_t flags;             // bit0 = collidable
};

