template <typename PR>
struct ClothBehaviorParams {
    PR stretch, shear, bend;
    PR thickness;
};

// FastGridCloth rest lengths are PER DIRECTION (6 values), not 3 scalars.
// A single stretch/shear/bend scalar only holds for a uniformly scaled
// grid; a non-uniform scale (e.g. 3x on X, 1x on Y) gives the column
// edges, row edges, the two cell diagonals, and the two bend spans all
// different rest lengths. Grid layout (MeshGridInitializer, row-major,
// idx = row*pn1D + col):
//   stretchRestX : idx 0  -> idx 1            (col +1, horizontal edge)
//   stretchRestY : idx 0  -> idx pn1D         (row +1, vertical edge)
//   shearRestA   : idx 0  -> idx pn1D+1       ("\" diagonal, +row +col)
//   shearRestB   : idx 1  -> idx pn1D         ("/" diagonal, +row -col)
//   bendRestX    : idx 0  -> idx 2            (col +2, horizontal bend)
//   bendRestY    : idx 0  -> idx 2*pn1D       (row +2, vertical bend)
// Field order MUST stay byte-identical to physics.metal's ClothGridParams
// (sent verbatim via setBytes; all members are 4-byte scalars, no pad).
template <typename PR>
struct FastGridClothBehaviorParams {
    uint particleNum1D;
    PR stretchRestX, stretchRestY;
    PR shearRestA,   shearRestB;
    PR bendRestX,    bendRestY;
    PR kstretch, kshear, kbend;
    PR thickness;
};

template <typename PR>
struct FloatBehaviorParams {};

template <typename PR>
using BehaviorParams = std::variant<
    ClothBehaviorParams<PR>,
    FastGridClothBehaviorParams<PR>,
    FloatBehaviorParams<PR>
>;

// Derive FastGridCloth's 6 directional rest lengths from the LIVE grid
// geometry. FastGridCloth physics reads these scalars directly (the
// metal kernel routes each spring to its matching field), NOT the
// adjacency restEdgeLengths arrays — so recomputeRestLengths() alone
// leaves a scaled FastGrid sheet pre-stressed. Measuring from the
// post-transform coordinates makes a uniformly OR non-uniformly scaled
// sheet's rest config fall out naturally. Each value is only written
// when its sample indices are in range and the measured length is
// non-degenerate, so a collapsed axis can't zero out a rest length and
// a too-small grid leaves the constructed defaults intact.
template <typename PR>
inline void recomputeFastGridRest(const PR* x, Index numPoints,
                                  FastGridClothBehaviorParams<PR>& p) {
    uint pn = p.particleNum1D;
    if (pn < 2 || x == nullptr) return;
    auto dist = [&](Index a, Index b) {
        PR dx = x[a*3+0] - x[b*3+0];
        PR dy = x[a*3+1] - x[b*3+1];
        PR dz = x[a*3+2] - x[b*3+2];
        return std::sqrt(dx*dx + dy*dy + dz*dz);
    };
    auto set = [&](PR& dst, Index a, Index b) {
        if (a < numPoints && b < numPoints) {
            PR d = dist(a, b);
            if (d > PR(1e-9)) dst = d;
        }
    };
    const Index P = (Index)pn;
    set(p.stretchRestX, 0, 1);        // col +1
    set(p.stretchRestY, 0, P);        // row +1
    set(p.shearRestA,   0, P + 1);    // "\" diagonal
    set(p.shearRestB,   1, P);        // "/" diagonal
    set(p.bendRestX,    0, 2);        // col +2
    set(p.bendRestY,    0, 2 * P);    // row +2
}

//! Force accumulator
template <typename BE, typename PR>
struct TriangularClothBehavior {};

template <typename PR>
struct TriangularClothBehavior<METAL, PR> {

    static MTL::ComputePipelineState* getPSO() {
        static MTL::ComputePipelineState* pso = nullptr;
        if (!pso) {
            pso = MetalKernelContext::getPSO("compute_tri_spring_forces");
        }
        return pso;
    }

    template <typename SimParams>
    static void setBuffer(
            GeneralMesh<METAL, PR>& mesh,
            SimParams& simParams) {
        Index offset = 0;
        // state 0-3
        MetalGlobalContext::setBuffer(mesh.state.x, offset++);
        MetalGlobalContext::setBuffer(mesh.state.v, offset++);
        MetalGlobalContext::setBuffer(mesh.state.f, offset++);
        MetalGlobalContext::setBuffer(mesh.state.m, offset++);
        // constraints 4-6
        MetalGlobalContext::setBuffer(mesh.constraints.fixedParticles, offset++);
        //MetalGlobalContext::setBuffer(mesh.constraints.vertexColPrims, offset++);
        //MetalGlobalContext::setBuffer(mesh.constraints.vertexColPrimsOffsets, offset++);
        MetalGlobalContext::setBuffer(Scene<METAL,PR>::packedCollisionData.vertColFacets, offset++);
        MetalGlobalContext::setBuffer(Scene<METAL,PR>::packedCollisionData.vertColFacetsOffsets, offset++);
        // external forces 7
        MetalGlobalContext::setBuffer(mesh.externalForces.externalForces, offset++);
        //simulation parameters 8-9
        MetalGlobalContext::setBytes(simParams, offset++);
        {
            // "팽팽함": scale a COPY of the cloth stiffness so the
            // stored base params stay intact; only the simulated
            // stretch/shear/bend are multiplied.
            ClothBehaviorParams<PR> cp =
                std::get<ClothBehaviorParams<PR>>(mesh.behaviorParams);
            PR s = mesh.clothStiffnessScale;
            cp.stretch *= s; cp.shear *= s; cp.bend *= s;
            MetalGlobalContext::setBytes(cp, offset++);
        }
        // adjacency 10-11
        MetalGlobalContext::setBuffer(mesh.adjacency.edges, offset++);
        MetalGlobalContext::setBuffer(mesh.adjacency.facets, offset++);
        // stretch springs 12-14
        MetalGlobalContext::setBuffer(mesh.adjacency.vertexAdjEdges, offset++);
        MetalGlobalContext::setBuffer(mesh.adjacency.vertexAdjEdgesOffsets, offset++);
        MetalGlobalContext::setBuffer(mesh.adjacency.restEdgeLengths, offset++);
        // bend springs 15-17
        MetalGlobalContext::setBuffer(mesh.adjacency.vertexOppVertices, offset++);
        MetalGlobalContext::setBuffer(mesh.adjacency.vertexOppVerticesOffsets, offset++);
        MetalGlobalContext::setBuffer(mesh.adjacency.restOppLengths, offset++);
        // packed data
        MetalGlobalContext::setBuffer(Scene<METAL, PR>::packedMeshData.statesOffsets, offset++);
        MetalGlobalContext::setBytes(mesh.id, offset++);
    }

    static void update(MeshState<METAL, PR>& state) {
        auto* pso = getPSO();
        size_t vertexNum = state.x.size/3;
        MetalGlobalContext::dispatchThreads(pso, vertexNum);
    }
};

template <typename BE, typename PR>
struct FastGridClothBehavior {};

template <typename PR>
struct FastGridClothBehavior<METAL, PR> {
    static MTL::ComputePipelineState* getPSO() {
        static MTL::ComputePipelineState* pso = nullptr;
        if (!pso) {
            pso = MetalKernelContext::getPSO("compute_cloth_grid_forces_fast");
        }
        return pso;
    }

    template <typename SimParams>
    static void setBuffer(
            GeneralMesh<METAL, PR>& mesh,
            SimParams& simParams) {
        Index offset = 0;
        // state 0-3
        MetalGlobalContext::setBuffer(mesh.state.x, offset++);
        MetalGlobalContext::setBuffer(mesh.state.v, offset++);
        MetalGlobalContext::setBuffer(mesh.state.f, offset++);
        MetalGlobalContext::setBuffer(mesh.state.m, offset++);
        // constraints 4-6
        MetalGlobalContext::setBuffer(mesh.constraints.fixedParticles, offset++);
        //MetalGlobalContext::setBuffer(mesh.constraints.vertexColPrims, offset++);
        //MetalGlobalContext::setBuffer(mesh.constraints.vertexColPrimsOffsets, offset++);
        MetalGlobalContext::setBuffer(Scene<METAL, PR>::packedCollisionData.vertColFacets, offset++);
        MetalGlobalContext::setBuffer(Scene<METAL, PR>::packedCollisionData.vertColFacetsOffsets, offset++);
        // external forces 7
        MetalGlobalContext::setBuffer(mesh.externalForces.externalForces, offset++);
        //simulation parameters 8-9
        MetalGlobalContext::setBytes(simParams, offset++);
        {
            // "팽팽함": scale the k* stiffness (NOT the rest lengths).
            FastGridClothBehaviorParams<PR> fp =
                std::get<FastGridClothBehaviorParams<PR>>(mesh.behaviorParams);
            PR s = mesh.clothStiffnessScale;
            fp.kstretch *= s; fp.kshear *= s; fp.kbend *= s;
            MetalGlobalContext::setBytes(fp, offset++);
        }
        //// adjacency 10-11
        //MetalGlobalContext::setBuffer(mesh.adjacency.edges, offset++);
        //MetalGlobalContext::setBuffer(mesh.adjacency.facets, offset++);
        //// stretch springs 12-14
        //MetalGlobalContext::setBuffer(mesh.adjacency.vertexAdjEdges, offset++);
        //MetalGlobalContext::setBuffer(mesh.adjacency.vertexAdjEdgesOffsets, offset++);
        //MetalGlobalContext::setBuffer(mesh.adjacency.restEdgeLengths, offset++);
        //// bend springs 15-17
        //MetalGlobalContext::setBuffer(mesh.adjacency.vertexOppVertices, offset++);
        //MetalGlobalContext::setBuffer(mesh.adjacency.vertexOppVerticesOffsets, offset++);
        //MetalGlobalContext::setBuffer(mesh.adjacency.restOppLengths, offset++);

        MetalGlobalContext::setBuffer(Scene<METAL, PR>::packedMeshData.statesOffsets, offset++);
        MetalGlobalContext::setBytes(mesh.id, offset++);
    }

    static void update(MeshState<METAL, PR>& state) {
        auto* pso = getPSO();
        size_t vertexNum = state.x.size/3;
        MetalGlobalContext::dispatchThreads(pso, vertexNum);
    }
};

struct Material {
    tinym::vec3 baseColor = tinym::vec3(1.0f);
    float metallic = 0.0f;
    float roughness = 0.5f;
    float specularWeight = 1.0f;
    tinym::vec3 emissionColor = tinym::vec3(0.0f);
};

// D-037: `struct Quat` definition lives in `include/Quat.hpp` (included near
// the top of this file). Body unchanged; only the physical location moved so
// `include/RigidPhysicsTypes.hpp` (RigidInitial holds Quat by value) can see
// the complete type. Helper functions (operator*, quatNormalize, etc.) stay
// in this file below.

// D-019: canonical quaternion math. Hamilton product convention is `a * b
// = apply b first, then a` — i.e., to rotate by R1 then R2, write R2 * R1.
// Free functions so they pair with the bare struct without changing its
// aggregate-init shape (the on-disk schema relies on the {w, x, y, z}
// member order). Future rotation consumers (FR-004 inspector wiring,
// FR-008 rigid body, eventual renderer-side rotation) should use these
// rather than reimplementing the math.
inline Quat operator*(const Quat& a, const Quat& b) {
    Quat r;
    r.w = a.w*b.w - a.x*b.x - a.y*b.y - a.z*b.z;
    r.x = a.w*b.x + a.x*b.w + a.y*b.z - a.z*b.y;
    r.y = a.w*b.y - a.x*b.z + a.y*b.w + a.z*b.x;
    r.z = a.w*b.z + a.x*b.y - a.y*b.x + a.z*b.w;
    return r;
}

inline float quatNorm(const Quat& q) {
    return std::sqrt(q.w*q.w + q.x*q.x + q.y*q.y + q.z*q.z);
}

inline Quat quatNormalize(const Quat& q) {
    float n = quatNorm(q);
    if (n < 1e-12f) return Quat{};
    return Quat{q.w/n, q.x/n, q.y/n, q.z/n};
}

// D-022: extends D-019's canonical Quat math family.
// quatConjugate flips the sign of the imaginary parts; for unit
// quaternions it equals the inverse, which is what rotation
// composition uses. rotateVector applies the canonical Hamilton
// sandwich q * v_pure * conjugate(q) — D-019's operator* left-
// associates so the expression reads as written. Caller must pass a
// unit-norm q (callers that build rotations via quatAxisAngle or
// quatNormalize satisfy this).
inline Quat quatConjugate(const Quat& q) {
    return Quat{q.w, -q.x, -q.y, -q.z};
}

inline tinym::vec3 rotateVector(const Quat& q, const tinym::vec3& v) {
    Quat vp{0.0f, v.x, v.y, v.z};
    Quat r = q * vp * quatConjugate(q);
    return tinym::vec3(r.x, r.y, r.z);
}

// D-035: inspector rotation ergonomics — conversion helpers between
// the canonical Quat representation and user-facing Euler / axis-angle
// forms. Free functions next to D-019/D-022's quat family, by the same
// convention. Inspector widgets display values in degrees; these
// helpers operate in radians internally — degree conversion happens
// at the inspector boundary.
//
// quatFromAxisAngle: auto-normalizes the axis. If axis-norm < 1e-12,
// returns identity (caller intent is ambiguous; identity is the safe
// fallback). Angle is in radians.
inline Quat quatFromAxisAngle(tinym::vec3 axis, float angleRadians) {
    float n = std::sqrt(axis.x * axis.x + axis.y * axis.y + axis.z * axis.z);
    if (n < 1e-12f) return Quat{};
    float nx = axis.x / n;
    float ny = axis.y / n;
    float nz = axis.z / n;
    float half = angleRadians * 0.5f;
    float s = std::sin(half);
    return Quat{std::cos(half), nx * s, ny * s, nz * s};
}

// quatToAxisAngle: inverse of quatFromAxisAngle. Returns angle in
// [0, π] and a unit-norm axis. Identity-quat fallback: angle=0,
// axis=(1, 0, 0) canonical. Caller passes a unit-norm q.
//
// Turn-30 fix (BLOCK closure for D-035): input is antipodally
// canonicalized at entry (negate all 4 components when q.w < 0) so
// qw ∈ [0, 1] always, acos(qw) ∈ [0, π/2], and the returned angle
// stays in [0, π] by construction. Without this, q = (-1, 0, 0, 0)
// (the antipodal identity / 360° rotation case) produced
// s = sqrt(1 - qw²) = 0 and axis = q.x/s = NaN/inf — the BLOCK
// surfaced by Estimator turn 30. After canonicalization, qw = +1 →
// acos(1) = 0 → the identity-fallback branch catches it cleanly.
inline void quatToAxisAngle(const Quat& q, tinym::vec3& outAxis,
                            float& outAngleRadians) {
    // Antipodal canonicalization: q and -q represent the same
    // rotation; pick the q.w >= 0 representative.
    float qw = q.w, qx = q.x, qy = q.y, qz = q.z;
    if (qw < 0.0f) {
        qw = -qw; qx = -qx; qy = -qy; qz = -qz;
    }
    // Clamp qw to [0, 1] to guard against tiny rounding overshoot
    // (acos is undefined outside [-1, 1]; after canonicalization the
    // valid range is [0, 1]).
    if (qw > 1.0f) qw = 1.0f;
    outAngleRadians = 2.0f * std::acos(qw);
    if (outAngleRadians < 1e-6f) {
        outAxis = tinym::vec3(1.0f, 0.0f, 0.0f);
        outAngleRadians = 0.0f;
        return;
    }
    float s = std::sqrt(1.0f - qw * qw);
    outAxis = tinym::vec3(qx / s, qy / s, qz / s);
}

// quatFromEulerXYZ: intrinsic Tait-Bryan XYZ.
//   rotation = R_z(zRad) * R_y(yRad) * R_x(xRad)
// "Apply X first in body frame, then Y, then Z" — matches Blender's
// default Euler convention. Compose via three axis-angle quaternions
// using D-019's Hamilton product (`a * b = apply b first then a`).
inline Quat quatFromEulerXYZ(float xRad, float yRad, float zRad) {
    Quat qx = quatFromAxisAngle(tinym::vec3(1.0f, 0.0f, 0.0f), xRad);
    Quat qy = quatFromAxisAngle(tinym::vec3(0.0f, 1.0f, 0.0f), yRad);
    Quat qz = quatFromAxisAngle(tinym::vec3(0.0f, 0.0f, 1.0f), zRad);
    return qz * qy * qx;
}

// quatToEulerXYZ: extract Tait-Bryan XYZ from a unit-norm Quat using
// the standard formulas (see e.g., Diebel 2006 "Representing Attitude").
// Output is in radians, with pitch (Y) in [-π/2, π/2]. Gimbal-lock
// fallback: when |sinp| ≥ 1 - 1e-6 (within 0.0257° of pitch=±90°),
// set roll (X) = 0 and derive yaw (Z) from the residual. The
// round-trip through gimbal lock is lossy by design — Euler cannot
// uniquely represent gimbal-locked rotations. Documented in D-035.
inline void quatToEulerXYZ(const Quat& q, float& outX, float& outY,
                           float& outZ) {
    // sinp = 2 * (q.w * q.y - q.z * q.x) corresponds to sin(pitch)
    // in this Tait-Bryan XYZ convention.
    float sinp = 2.0f * (q.w * q.y - q.z * q.x);
    if (sinp > 1.0f) sinp = 1.0f;
    else if (sinp < -1.0f) sinp = -1.0f;
    if (std::abs(sinp) >= 1.0f - 1e-6f) {
        // Gimbal lock. Pitch is ±π/2; collapse roll into yaw.
        outY = (sinp > 0.0f) ? (3.14159265358979323846f * 0.5f)
                             : (-3.14159265358979323846f * 0.5f);
        outX = 0.0f;
        outZ = 2.0f * std::atan2(q.z, q.w);
    } else {
        outY = std::asin(sinp);
        outX = std::atan2(2.0f * (q.w * q.x + q.y * q.z),
                          1.0f - 2.0f * (q.x * q.x + q.y * q.y));
        outZ = std::atan2(2.0f * (q.w * q.z + q.x * q.y),
                          1.0f - 2.0f * (q.y * q.y + q.z * q.z));
    }
}

// Row-major 3x3 from a unit quaternion — the body-rotation input of
// kinematic::BodyProxy::writeVertices (which is Quat/tinym-free).
inline std::array<float, 9> quatToMat3(const Quat& q) {
    const float w = q.w, x = q.x, y = q.y, z = q.z;
    return {1 - 2 * (y * y + z * z), 2 * (x * y - w * z), 2 * (x * z + w * y),
            2 * (x * y + w * z), 1 - 2 * (x * x + z * z), 2 * (y * z - w * x),
            2 * (x * z - w * y), 2 * (y * z + w * x), 1 - 2 * (x * x + y * y)};
}

// ---- BVH kinematic body ----------------------------------------------------

template <typename PR>
struct MeshKinematicInitializerParams : InitializerParams<PR> {
    std::string filePath;   // source .bvh
    tinym::vec3 center;
    // Normalized body height in scene units; the FK pose (whose raw units
    // vary ~7x across assets/BVH) is uniformly scaled so its rest height
    // equals this BEFORE the user transform applies.
    PR targetHeight;

    MeshKinematicInitializerParams(std::string filePath, tinym::vec3 center,
                                   Index numPoints, Index numFacets,
                                   Index numEdges, PR targetHeight, PR mass)
        : InitializerParams<PR>(numPoints, numFacets, numEdges, mass),
          filePath(std::move(filePath)), center(center),
          targetHeight(targetHeight) {}
};

// One GeneralMesh per kinematic body: the concatenated sphere(joint) +
// cylinder(link) proxy carries a single mesh id, so picking any part
// selects the whole body and its triangles ride the existing collision
// pipeline. The initializer owns motion + proxy + playback state because
// the initializer object (held by the request) is the only per-mesh
// state that survives Scene::pack rebuilds.
template <typename BE, typename PR>
struct MeshKinematicInitializer : GeneralMeshInitializer<BE, PR> {
    using ParamsType = MeshKinematicInitializerParams<PR>;
    ParamsType params;

    bvh::Motion motion;
    kinematic::BodyProxy proxy;

    // Playback state (driven by Simulator::update with the sim step h, so
    // motion time IS simulation time — pausing the sim pauses the body).
    bool playing = true;
    float playSpeed = 1.0f;
    bool loop = true;
    double localTime = 0.0;

    // ── Motion-graph playback (Kovar 2002, include/motion_graph.hpp) ──
    // motionMode picks the pose source: 0 = single clip (the original path,
    // untouched), 1 = graph random walk, 2 = graph transition. A graph mode
    // only engages once its session build succeeded (graphActive()); until
    // then the single clip keeps playing, so a half-configured panel never
    // blanks the body. The staging fields are inspector state that must
    // survive re-packs, which is why they live here with the playback state.
    int motionMode = 0;
    mograph::Session graphSession;
    std::vector<std::string> graphSelFiles;  // random-walk clip set (file names)
    std::string transFileA, transFileB;      // transition endpoints (file names)
    float graphThreshold = 0.10f;            // cost threshold, fraction of height
    float graphMarkerFrac = 0.10f;           // joint-axis marker length / height
    uint32_t walkSeed = 12345;
    std::string graphStatus;                 // last build report for the GUI

    // Blend-mode motion preview: independent per-clip strobe, available before
    // 블렌드 생성 — samples the selected files directly (cached) rather than the
    // built session's clips. Colors are user-pickable.
    bool previewA = false, previewB = false;
    std::array<float, 3> previewColA{0.95f, 0.25f, 0.25f};  // motion 1 (red)
    std::array<float, 3> previewColB{0.30f, 0.45f, 0.95f};  // motion 2 (blue)
    // Blend playback tint: when on (blend mode only), the live body is colored
    // by mixing previewColA/B by the current blend source weight, so you see
    // which source motion dominates as the crossfade plays.
    bool blendColorize = false;
    mograph::Clip previewClipA, previewClipB;
    std::string previewFileA, previewFileB;  // which file each cache holds
    // One-shot opaque playback (paused-only, render-loop driven): 0 none,
    // 1 = motion A playing, 2 = motion B playing. Clears itself at clip end.
    int previewPlay = 0;
    double previewPlayTime = 0.0;

    // Reference skeleton (the loaded motion's), cached for preview FK + clip
    // sampling. Invalidated on reloadMotion.
    mograph::Skeleton skelCache_;
    bool skelValid_ = false;
    const mograph::Skeleton& skel() {
        if (!skelValid_) {
            skelCache_ = mograph::Skeleton::extract(motion);
            skelValid_ = true;
        }
        return skelCache_;
    }

    bool graphActive() const {
        if (!graphSession.ready()) return false;
        if (motionMode == 1)
            return graphSession.mode == mograph::Session::Mode::RandomWalk;
        if (motionMode == 2)
            return graphSession.mode == mograph::Session::Mode::Transition;
        if (motionMode == 3)
            return graphSession.mode == mograph::Session::Mode::Blend;
        return false;
    }

    // Playback length of whatever the current mode plays (walks are
    // effectively unbounded).
    double activeDuration() const {
        return graphActive() ? graphSession.duration()
                             : (double)motion.duration();
    }

    explicit MeshKinematicInitializer(ParamsType p) : params(std::move(p)) {}

    // Factory: loads + builds first because InitializerParams needs the
    // vertex/facet/edge counts at construction. Returns nullptr (with
    // `err` filled) on parse failure.
    static MeshKinematicInitializer* create(const std::string& path,
                                            tinym::vec3 center,
                                            PR targetHeight, PR mass,
                                            std::string* err = nullptr) {
        bvh::Motion m = bvh::load(path, err);
        if (!m.valid()) return nullptr;
        kinematic::BodyProxy proxy;
        proxy.build(m);
        auto* init = new MeshKinematicInitializer(ParamsType(
            path, center, proxy.numVerts, proxy.numFacets(), proxy.numEdges,
            targetHeight, mass));
        init->motion = std::move(m);
        init->proxy = std::move(proxy);
        return init;
    }

    // Swap the motion source in place. Topology may change (different
    // skeleton), so the caller must mark the scene dirty for a re-pack.
    bool reloadMotion(const std::string& path, std::string* err = nullptr) {
        bvh::Motion m = bvh::load(path, err);
        if (!m.valid()) return false;
        kinematic::BodyProxy p;
        p.build(m);
        motion = std::move(m);
        proxy = std::move(p);
        params.filePath = path;
        params.numPoints = proxy.numVerts;
        params.numFacets = proxy.numFacets();
        params.numEdges = proxy.numEdges;
        localTime = 0.0;
        // A built graph session references the OLD motion's skeleton/units;
        // keep it from driving the new proxy. Builders reload first, then
        // rebuild the session, so this only ever drops stale state.
        graphSession.clear();
        // Skeleton + preview caches reference the old motion — drop them.
        skelValid_ = false;
        previewFileA.clear();
        previewFileB.clear();
        previewClipA.frames.clear();
        previewClipB.frames.clear();
        invalidateRebase();
        return true;
    }

    float normScale() const {
        const float h = motion.restHeight();
        return h > 1e-6f ? float(params.targetHeight) / h : 1.0f;
    }

    // FK pose at `timeSec` → `out` (3*numPoints PR). Base variant used by
    // initialize/populatePreview: pose normalized + translated to center,
    // NO user scale/rotation — Scene::pack bakes those afterwards, same
    // as every other initializer.
    void writePoseBase(double timeSec, PR* out) {
        writePose(timeSec, tinym::vec3(1, 1, 1), Quat{}, params.center, out);
    }

    // Full variant used by the per-frame update, which overwrites the
    // pack-baked geometry and therefore must apply the user transform
    // itself (scale → rotate → translate around the FK origin).
    void writePose(double timeSec, tinym::vec3 userScale, const Quat& rot,
                   tinym::vec3 position, PR* out) {
        bvh::Pose pose;
        sampleWorldPose(timeSec, pose);
        applyRootRebase(pose);
        scratch_.resize(size_t(proxy.numVerts) * 3);
        proxy.writeVertices(
            pose, normScale(),
            {float(userScale.x), float(userScale.y), float(userScale.z)},
            quatToMat3(rot),
            {float(position.x), float(position.y), float(position.z)},
            scratch_.data());
        for (size_t i = 0; i < scratch_.size(); ++i) out[i] = PR(scratch_[i]);
    }

    // Sample the active source (graph session when built, else the raw clip)
    // into a world-space pose. Shared by playback and the frame-0 rebase.
    void sampleWorldPose(double timeSec, bvh::Pose& pose) {
        if (graphActive()) {
            graphSession.samplePose(timeSec, pose);
            // Joint-count mismatch would mean a session built against a
            // different skeleton than the proxy — fall back rather than
            // index out of bounds (builders prevent this; belt+braces).
            if (pose.world.size() != motion.joints.size())
                motion.evaluate(float(timeSec), loop, pose);
        } else {
            motion.evaluate(float(timeSec), loop, pose);
        }
    }

    // Cached live-playback rebase (frame-0 xz + yaw). Cached because for long
    // random walks WalkBaker evicts old frames, so re-sampling frame 0 later
    // would shift the origin and jump the body. Invalidated when the playback
    // source changes (mode/build/file/seed).
    bool rebaseValid_ = false;
    float rebaseTh_ = 0.0f, rebaseX0_ = 0.0f, rebaseZ0_ = 0.0f;
    void invalidateRebase() { rebaseValid_ = false; }

    // Re-root: the BVH frame-0 root xz position + heading (yaw) are removed so
    // the kinematic object's transform alone places the body (frame-0 root
    // sits at the object origin). Y is kept so feet stay grounded. Gravity-
    // preserving — same family as the motion-graph XformXZ.
    void applyRootRebase(bvh::Pose& pose) {
        if (pose.world.empty()) return;
        if (!rebaseValid_) {
            bvh::Pose p0;
            sampleWorldPose(0.0, p0);
            if (p0.world.empty()) return;
            const auto& R0 = p0.world[0].R;
            rebaseTh_ = std::atan2(R0[2], R0[0]);
            rebaseX0_ = p0.world[0].t[0];
            rebaseZ0_ = p0.world[0].t[2];
            rebaseValid_ = true;
        }
        const float c = std::cos(rebaseTh_), s = std::sin(rebaseTh_);
        for (auto& jx : pose.world) {
            const float dx = jx.t[0] - rebaseX0_, dz = jx.t[2] - rebaseZ0_;
            jx.t[0] = c * dx - s * dz;
            jx.t[2] = s * dx + c * dz;
        }
    }

    // In-place: rotate the whole pose by -yaw(root0) about Y and subtract
    // root0's xz, leaving Y untouched. (writeVertices only reads joint
    // positions, so re-rooting positions re-roots the visible body.)
    static void rebaseXZYaw(bvh::Pose& pose, const bvh::JointXform& root0) {
        const float th = std::atan2(root0.R[2], root0.R[0]);
        const float c = std::cos(th), s = std::sin(th);
        const float x0 = root0.t[0], z0 = root0.t[2];
        for (auto& jx : pose.world) {
            const float dx = jx.t[0] - x0, dz = jx.t[2] - z0;
            jx.t[0] = c * dx - s * dz;
            jx.t[2] = s * dx + c * dz;
        }
    }

    // Motion-preview ghost: proxy world verts for clip `c` frame `f`, re-rooted
    // exactly like the live body (frame-0 xz+yaw removed, Y kept) and placed by
    // the body transform — so it rests at the object's position, feet grounded.
    void writeGhost(const mograph::Clip& c, int f, tinym::vec3 userScale,
                    const Quat& rot, tinym::vec3 position,
                    std::vector<float>& out) {
        if (c.frames.empty()) return;
        const int nf = int(c.frames.size());
        const int fi = f < 0 ? 0 : (f >= nf ? nf - 1 : f);
        bvh::Pose pose, pose0;
        mograph::fk(skel(), c.frames[fi], pose);
        mograph::fk(skel(), c.frames[0], pose0);
        rebaseXZYaw(pose, pose0.world[0]);
        out.resize(size_t(proxy.numVerts) * 3);
        proxy.writeVertices(
            pose, normScale(),
            {float(userScale.x), float(userScale.y), float(userScale.z)},
            quatToMat3(rot),
            {float(position.x), float(position.y), float(position.z)},
            out.data());
    }

    // Like writeGhost but samples the clip at a continuous time (lerp between
    // frames) — for the smooth one-shot preview playback.
    void writeGhostAtTime(const mograph::Clip& c, double timeSec,
                          tinym::vec3 userScale, const Quat& rot,
                          tinym::vec3 position, std::vector<float>& out) {
        if (c.frames.empty()) return;
        const int nf = int(c.frames.size());
        double ff = timeSec / (c.dt > 0 ? c.dt : 1.0);
        if (ff < 0) ff = 0;
        if (ff > nf - 1) ff = nf - 1;
        const int f0 = int(ff);
        const int f1 = f0 + 1 < nf ? f0 + 1 : f0;
        const float frac = float(ff - f0);
        mograph::LocalPose mid;
        mograph::blendPose(c.frames[f0], c.frames[f1], 1.0f - frac, mid);
        bvh::Pose pose, pose0;
        mograph::fk(skel(), mid, pose);
        mograph::fk(skel(), c.frames[0], pose0);
        rebaseXZYaw(pose, pose0.world[0]);
        out.resize(size_t(proxy.numVerts) * 3);
        proxy.writeVertices(
            pose, normScale(),
            {float(userScale.x), float(userScale.y), float(userScale.z)},
            quatToMat3(rot),
            {float(position.x), float(position.y), float(position.z)},
            out.data());
    }

    void initialize(MeshState<BE, PR>& state,
                    MeshAdjacency<BE, PR>& adjacency) override {
        state.memoryAllocation(params);
        adjacency.memoryAllocation(params);

        // Current localTime (not 0) so a structural re-pack mid-playback
        // realizes the frame the user is looking at.
        writePoseBase(localTime, state.x.ptr);

        if (adjacency.vertexAdjFacets.ptr) return;
        for (Index f = 0; f < params.numFacets * 3; ++f)
            adjacency.facets[f] = proxy.facets[f];

        MeshAdjacencyInitializer<BE, PR>::initialize(state, adjacency);
    }

    void populatePreview(PreviewState<PR>& preview) override {
        std::vector<PR> x(size_t(params.numPoints) * 3);
        writePoseBase(localTime, x.data());
        preview.x.assign(x.begin(), x.end());
        preview.facets.assign(proxy.facets.begin(), proxy.facets.end());
        preview.recomputeNormals();
    }

    InitializerParams<PR>* getParams() override { return &params; }

  private:
    std::vector<float> scratch_;
};

template <typename BE, typename PR>
struct GeneralMesh {
    int id;
    // D-026: never-reused identity for BVH skip-cache invalidation. Set
    // at Scene::pack realization from RequestGeneralMesh::lifetimeId.
    // Distinct from `id` (which is numMeshes-derived and resets on
    // resetScene; D-018 RNG seed). See CM-008 (graduated).
    int lifetimeId = -1;


    MeshState<BE, PR> state;
    MeshAdjacency<BE, PR> adjacency;
    GeneralMeshInitializer<BE, PR>* initializer;
    BehaviorType behaviorType;
    ShapeType shapeType = ShapeType::Mesh;
    BehaviorParams<PR> behaviorParams;
    Material material;
    Quat rotationQuat;
    // World-space center mirror for the inspector translate path (BDD-003).
    // Mutated only by Simulator::translateObject; pack-time seeded from the
    // initializer's center/offset so existing meshes preserve their author
    // intent. Persists through saveScene/loadScene via Simulator::toSnapshot.
    tinym::vec3 transformPosition = tinym::vec3(0);
    // Per-axis world-space scale mirror for the inspector scale path.
    // Mutated only by Simulator::scaleObject; carried through Scene::pack
    // via RequestGeneralMesh::scale (geometry is preserved by the R-3
    // preview memcpy, this preserves the stored factor the inspector
    // shows and scaleObject composes its delta against). Default unit.
    tinym::vec3 scale = tinym::vec3(1.0f, 1.0f, 1.0f);
    // "팽팽함" — uniform multiplier applied to the cloth stiffness
    // (TriangularCloth stretch/shear/bend, FastGridCloth k*) at kernel
    // upload time. Base behaviorParams stay untouched; this scales the
    // SIMULATED stiffness. Default 1. Mirrored on RequestGeneralMesh so
    // it survives Scene::pack; round-trips through scene_format.
    PR clothStiffnessScale = PR(1);
    Constraints<BE, PR> constraints;
    ExternalForces<BE, PR> externalForces;

    // Per-object environment-force gates (UI-driven; default = receive both).
    // Honored by Simulator::applyEnvironmentForces — clearing applyGravity
    // omits the per-particle gravity term; clearing applyWind omits the
    // wind term (cloth only). Persisted via scene_format::Object.
    bool applyGravity = true;
    bool applyWind = true;

    // 고정(Static) 선언 — UI 토글. true면 이 메시는 움직이지 않는다고
    // 약속하는 것으로, BroadPhase가 매 substep BVH refit(리프 AABB 재계산)을
    // 건너뛴다. 한 번 build()된 트리 AABB를 그대로 재사용 → floating/floor
    // 류 정적 메시의 낭비되는 refit 제거. 충돌 '타깃'으로는 여전히 TLAS에
    // 참여한다(천이 정적 바닥 위로 떨어지는 경우). static을 켜면 inspector
    // 콜백이 applyGravity/applyWind를 자동으로 끈다(움직임 소스 제거).
    // Persisted via scene_format::Object; mirrored on RequestGeneralMesh.
    bool isStatic = false;

    // Plane checkerboard render option (UI-driven; plane/grid meshes only).
    // When true the renderer overrides the surface albedo with a world-space
    // black/white checker (1 world unit per cell) computed in the plane's
    // local frame — see Simulator::draw and shader.frag's checker* uniforms.
    // Mirrored on RequestGeneralMesh so it survives Scene::pack rebuilds.
    bool checkerboard = false;

    // Sub-object / cluster BVH per-object settings (UI-driven). clusterSplitS
    // = this mesh's split s (k=4^s clusters/tiles) — per-object so each mesh
    // divides to suit its size (maximizes the grid cluster-pair effect). -1
    // = inherit the global BroadPhase::subBvhSplitS (so headless benches that
    // set the global keep working; the GUI writes a concrete 1..8 per object).
    // clusterRender = color this mesh's triangles by cluster in the viewport.
    // Both mirrored on RequestGeneralMesh so they survive Scene::pack (the
    // '0' reset rebuilds BroadPhase from scratch; without the mirror these
    // GUI edits would be lost). The master cluster-mode switch is global
    // (Simulator::clusterModeOn / the profiler window), these are per-object.
    int  clusterSplitS = -1;
    bool clusterRender = false;

    // D-039: Rigid backend wiring. Set by Simulator::ensureRigidBackendBody
    // on Float→Rigid transition (changeBehavior) or initialize-time sweep.
    // kInvalidBodyHandle (-1) means "no backend body yet"; update() skips.
    int32_t rigidBodyHandle = ysim::physics::kInvalidBodyHandle;
    // Cached last backend body position so each frame's Δpos = current - last
    // can be applied to state.x / state.xPrev / transformPosition.
    tinym::vec3 rigidLastBodyPos = {};

    // Render-side GL state lives in MeshRenderState, keyed by id (D-011).
    // GeneralMesh no longer owns OpenGL handles, so initialize() is safe to
    // call from a non-GL context — that's the precondition for the upcoming
    // Metal-backed test harness.

    GeneralMesh(GeneralMeshInitializer<BE, PR>* initializer, BehaviorType behaviorType, BehaviorParams<PR> behaviorParams)
    : initializer(initializer), behaviorType(behaviorType), behaviorParams(behaviorParams) {}
    GeneralMesh(GeneralMesh&& other) noexcept
        : id(other.id),
          lifetimeId(other.lifetimeId),
          state(std::move(other.state)),
          adjacency(std::move(other.adjacency)),
          initializer(other.initializer),
          behaviorType(other.behaviorType),
          behaviorParams(other.behaviorParams),
          material(std::move(other.material)),
          rotationQuat(other.rotationQuat),
          transformPosition(other.transformPosition),
          scale(other.scale),
          clothStiffnessScale(other.clothStiffnessScale),
          constraints(std::move(other.constraints)),
          externalForces(std::move(other.externalForces)),
          applyGravity(other.applyGravity),
          applyWind(other.applyWind),
          isStatic(other.isStatic),
          checkerboard(other.checkerboard),
          clusterSplitS(other.clusterSplitS),
          clusterRender(other.clusterRender)
    {
        other.initializer = nullptr;
    }
    ~GeneralMesh() { delete initializer; }

    void initialize() {
        std::cout << "  - [GeneralMesh initialize] id " << id << " try to initialize\n";
        std::cout << "  - [GeneralMesh initialize] initializer " << initializer << "\n";
        initializer->initialize(state, adjacency);
        std::cout << "  - [GeneralMesh initialize] id " << id << " initializer init\n";
        constraints.memoryAllocation(state.x.size/3);
        std::cout << "  - [GeneralMesh initialize] id " << id << " constraints init. finished.\n";
    }


};






struct Ray {
    tinym::vec3 origin;
    tinym::vec3 dir;
};


struct RayHit {
    Index obj;
    Index primId;
    float tmin, tmax;
};


struct SceneEnvironment {
    tinym::vec3 gravity = tinym::vec3(0.0f, -9.81f, 0.0f);
    tinym::vec3 wind    = tinym::vec3(0.0f, 0.0f, 0.0f);
    // D-028 follow-on: scene-global directional-light tint + magnitude.
    // The shader's `lightColor` uniform is set to (lightColor * lightIntensity)
    // each frame; defaults give white tint at ~1.6 radiance, matching the
    // tuned PBR-preview brightness from the initial D-028 commit. Not
    // currently persisted in scene_format (in-memory only) — promote to
    // schema if/when scene authoring needs lighting setups to survive
    // save/load.
    tinym::vec3 lightColor = tinym::vec3(1.0f, 1.0f, 1.0f);
    float       lightIntensity = 1.6f;
    // Viewport clear color. Read by the render loop each frame and pushed
    // through glClearColor; mirrored into scene_format::Environment so
    // saveScene/loadScene round-trip the choice.
    tinym::vec3 backgroundColor = tinym::vec3(0.886f, 0.906f, 0.922f); // #E2E7EB gray20
};

template <typename BE, typename PR>
struct Scene {
    inline static int numMeshes = 0;
    // D-026: never-resetting monotone counter for per-mesh lifetime
    // identity. Distinct from numMeshes (which resets on resetScene
    // and is the D-018 RNG seed). Used by BroadPhase::build to gate
    // the Float-mesh skip — see CM-008 (graduated).
    inline static int lifetimeMeshCount = 0;
    // Vestigial. id is no longer a monotone counter: it is the compacted
    // [0, numMeshes) array slot, (re)assigned in addGeneralMesh /
    // removeMesh / Scene::pack so it always equals the request's index
    // (== statesOffsets / objTrees / faceObj subscript == objPair). The
    // old monotone scheme avoided MeshRenderState id reuse by never
    // compacting; removeMesh now rebuilds the id-keyed render cache
    // instead. Kept (still zeroed by loadScene) only to avoid churning
    // that reset path; nothing reads it for id assignment anymore.
    inline static int nextMeshId = 0;

    inline static std::vector<GeneralMesh<BE, PR>> meshes;
    inline static SceneEnvironment environment;

    struct RequestGeneralMesh {
        int id;
        int lifetimeId;
        GeneralMeshInitializer<BE, PR>* initializer;
        BehaviorType behaviorType;
        BehaviorParams<PR> behaviorParams;
        // Mirror of GeneralMesh.applyGravity / applyWind kept on the
        // request so per-mesh environment-force toggles survive
        // Scene::pack rebuilds (initialize / reset / loadScene). pack
        // copies these into the realized mesh; the inspector callback
        // writes here in addition to the live mesh field. Both default
        // true (matches GeneralMesh defaults).
        bool applyGravity = true;
        bool applyWind = true;
        // Mirror of GeneralMesh.isStatic kept on the request so the static
        // declaration survives Scene::pack rebuilds (reset / load /
        // changeBehavior). pack copies this onto the realized mesh; the
        // inspector callback writes here in addition to the live field.
        bool isStatic = false;
        // Mirror of GeneralMesh.checkerboard (plane render option) kept on
        // the request so the toggle survives Scene::pack rebuilds. pack
        // copies this onto the realized mesh; the inspector callback writes
        // here in addition to the live mesh field. Default off.
        bool checkerboard = false;
        // Mirror of GeneralMesh.clusterSplitS / clusterRender (per-object
        // sub-object BVH split count + cluster-color render). The '0' reset
        // wipes BroadPhase entirely, so these per-object GUI edits must ride
        // the request through pack. Defaults: s=-1 (inherit global), render off.
        int  clusterSplitS = -1;
        bool clusterRender = false;
        // Mirror of GeneralMesh.rotationQuat kept on the request so the
        // user's orientation survives Scene::pack rebuilds (initialize /
        // reset / loadScene). Without this, pack rebuilds meshes from the
        // initializer with a default identity quat — the geometry stays
        // rotated (carried by preview's R-3 memcpy) but the stored
        // quaternion (what the inspector displays and what rotateObject
        // composes deltas against) snapped back to identity. pack copies
        // this into the realized mesh; rotateObject writes here in
        // addition to the live mesh field. Defaults to identity.
        ::Quat rotationQuat{};
        // Mirror of GeneralMesh.scale kept on the request so the user's
        // per-axis scale survives Scene::pack rebuilds, same rationale as
        // rotationQuat above. pack copies this onto the realized mesh;
        // scaleObject writes here in addition to the live mesh field.
        tinym::vec3 scale = tinym::vec3(1.0f, 1.0f, 1.0f);
        // Mirror of GeneralMesh.clothStiffnessScale ("팽팽함") so the
        // multiplier survives Scene::pack rebuilds. Default 1.
        PR clothStiffnessScale = PR(1);
        // S3-2: material owned by the request (single source of truth).
        // pack copies this onto the realized mesh; setMaterial writes
        // here + the live mesh in place (no re-pack — a value
        // overwrite). Replaces the pendingMaterials side-map.
        ::Material material{};
        // Pinned-vertex constraints (point-selection panel). Source of
        // truth for which vertices are fixed and where: Scene::pack
        // re-applies these into constraints.fixedParticles + state.x +
        // preview every rebuild, and scene_format round-trips them.
        // setVertexFixed / translateVertexTo keep this in sync with the
        // live mesh. vid is the PHYSICS vertex index.
        std::vector<FixedVertex> fixedVertices;
        // D-042 R-1: heap-owned vertex/facet/normal preview, populated by
        // initializer->populatePreview() at addGeneralMesh time. Stays
        // alive across Scene::pack / pool-reset cycles. R-2 will point
        // MeshGL here for stable pre-pack rendering; R-5 will sync the
        // packedMeshData → preview after every Simulator::update.
        PreviewState<PR> preview;

        RequestGeneralMesh(int id, int lifetimeId,
                           GeneralMeshInitializer<BE, PR> *initializer,
                           BehaviorType behaviorType,
                           BehaviorParams<PR> behaviorParams)
            : id(id), lifetimeId(lifetimeId), initializer(initializer),
              behaviorType(behaviorType),
              behaviorParams(std::move(behaviorParams)) {}
    };

    inline static std::vector<RequestGeneralMesh> requestsGeneralMeshes;
    // Reference-point coincidence constraints (point panel). Scene-static
    // so it survives Scene::pack and Simulator::reset (neither clears it);
    // loadScene rebuilds the scene and explicitly restores this from the
    // snapshot. The integrator enforces query↔target position coincidence.
    inline static std::vector<ReferencePointConstraint> referenceConstraints;
    inline static bool dirty = true;

    void addGeneralMesh(GeneralMeshInitializer<BE, PR>* initializer, BehaviorType behaviorType, BehaviorParams<PR> behaviorParams) {
        //meshes.emplace_back(initializer, behaviorType, behaviorParams);
        //meshes.back().id = numMeshes++;

        // id is the compacted [0, numMeshes) slot that governs ALL mesh
        // access — findById AND packed-data subscripts (statesOffsets,
        // objTrees, faceObj) AND objPair in collisions. It equals the
        // request's position in requestsGeneralMeshes, which (since we
        // only append here and removeMesh renumbers) is always numMeshes.
        // It is internal logic only, never persisted as an identity:
        // save/load and removeMesh both re-derive it from load/array
        // order. lifetimeId stays the monotone never-reused identity
        // (D-026 BVH Float-skip gate); id and lifetimeId are distinct on
        // purpose — id is volatile, lifetimeId is stable.
        int newId = (int)requestsGeneralMeshes.size();
        requestsGeneralMeshes.emplace_back(newId, lifetimeMeshCount++,
                                           initializer, behaviorType, behaviorParams);
        numMeshes++;

        // D-042 R-1: populate preview state directly from the initializer
        // (heap-owned vector buffers). After this call, the new request's
        // preview.x / preview.facets / preview.n are ready for renderer
        // consumption — no need to wait for Scene::pack. Subtypes that
        // haven't migrated yet hit the default no-op and leave preview
        // empty (acceptable until R-2 makes preview load-bearing).
        requestsGeneralMeshes.back().initializer->populatePreview(
            requestsGeneralMeshes.back().preview);

        dirty = true;

        //std::cout << "id " << meshes.back().id << " object is created\n";
    }


    struct PackedMeshData {
        // MeshState
        VectorBase<BE, PR> x;
        // xPrev: start-of-substep snapshot of x; consumed by the swept-segment
        // narrow phase (D-013). Sliced into per-mesh state.xPrev.
        VectorBase<BE, PR> xPrev;
        VectorBase<BE, PR> v;
        VectorBase<BE, PR> f;
        VectorBase<BE, PR> m;
        VectorBase<BE, PR> n;
        // External-forces buffer consumed by the cloth kernels
        // (TriangularClothBehavior / FastGridClothBehavior). Sliced into per
        // mesh externalForces.externalForces, filled per frame from
        // Scene::environment by Simulator::applyEnvironmentForces.
        VectorBase<BE, PR> externalForces;
        // MeshAdjacency
        VectorBase<BE, Index> facets;
        VectorBase<BE, Index> edges;
        VectorBase<BE, Index> vertexAdjFacets, vertexAdjFacetsOffsets;
        VectorBase<BE, Index> vertexAdjEdges, vertexAdjEdgesOffsets;

        // offset data by id
        VectorBase<BE, Index> statesOffsets;
        VectorBase<BE, Index> facetsOffsets;
        VectorBase<BE, Index> edgesOffsets;
        // Slice (c) A1: owning mesh index per packed vertex (size
        // numPoints), built once per Scene::pack from statesOffsets.
        // Lets the analytic narrow kernel resolve thread→mesh (and its
        // behavior via meshBehaviors) without an in-kernel binary
        // search over statesOffsets. Inert until c-1 consumes it.
        VectorBase<BE, Index> vertObj;
    };
    inline static PackedMeshData packedMeshData;

    struct PackedCollisionData {
        VectorBase<BE, BroadCollision> broadCollisions;
        VectorBase<BE, Index> numBroadCollisions;
        VectorBase<BE, NarrowCollision> narrowCollisions;
        VectorBase<BE, Index> numNarrowCollisions;
        // Cumulative across substeps; the per-substep `numNarrowCollisions[0]`
        // resets in `resetNarrow()`. The self-test reads this to verify
        // contacts ever fired during a frame loop (BDD-007 acceptance).
        size_t cumulativeNarrowCollisions = 0;
        Index approxColsPerPoints = 15;
        Index maxNumCollisions;
        VectorBase<BE, NarrowCollision> vertColFacets;
        VectorBase<BE, Index> vertColFacetsOffsets;
        // P4 GPU bucketing scratch: per-vertex running offset the scatter
        // kernel atomic-bumps (size numPoints). vertColFacetsOffsets doubles
        // as histogram-then-CSR (scanned in place), so no scan scratch.
        VectorBase<BE, Index> vertColBucketCounter;

        // Segmented (per-threadgroup) detect+reduce scratch — used by
        // BVH::queryPointsSegmented (paper-inspired alternative to the
        // baseline per-leaf-hit global atomic). Allocated alongside
        // broadCollisions in pack(). Worst-case size: ceil(numPoints
        // / segTGSize) threadgroups, each holding up to segPerTGCap
        // BroadCollisions. Reused across all (q,t) calls in one
        // detectCollisionsSegmented frame; the global numBroadCollisions
        // counter (above) accumulates across calls as in the baseline.
        Index segTGSize     = 256;
        // Per-TG private slice budget multiplier on top of the global
        // per-point average (approxColsPerPoints). The baseline path
        // shares one global budget so hot-spot hits "borrow" capacity
        // from cold TGs; the segmented path partitions the budget
        // per-TG so hot TGs (Morton-clustered cloth points piling onto
        // the same ground patch) overflow well before the global cap.
        // 4× covers typical hot/cold ratio in the funnel/cloth-ball
        // benchmarks; raise if [queryPointsSegmented] still warns.
        Index segPerTGCapFactor = 4;
        Index segPerTGCap   = 0;   // = approxColsPerPoints * segTGSize * factor, set in pack
        Index segMaxTGs     = 0;   // = ceil(numPoints / segTGSize),    set in pack
        VectorBase<BE, BroadCollision> segPrivateCollisions;
        VectorBase<BE, uint32_t>       segPrivateCount;
        VectorBase<BE, uint32_t>       segPrivateOffset;

        // Slice (c-2) — analytic-primitive broad markers. The BVH broad
        // phase, when the analytic toggle is on, finds (cloth query,
        // sphere target) object pairs whose top-level AABBs overlap and
        // records them HERE instead of descending the sphere's triangle
        // BVH (which would emit thousands of vertex×triangle BroadCollisions
        // that narrow_pt_tri then skips). narrowAnalytic() consumes these
        // — one dispatch per pair — so the analytic narrow phase only fires
        // when objects actually overlap (zero cost during the fall) and
        // tests one sphere per cloth instead of all clouds × all shapes.
        // clothObj = object/statesOffsets INDEX (D-041); shapeObjId = the
        // sphere mesh id, resolved to a compact AnalyticShape[] index in
        // narrowAnalytic. Cleared at the top of each broad detect and again
        // after narrow consumes it (so a later SH-broad frame, which does
        // not populate this, can't re-dispatch stale pairs).
        struct AnalyticBroadPair { Index clothObj; Index shapeObjId; };
        std::vector<AnalyticBroadPair> analyticPairs;

        void resetNarrow() {
            std::memset(narrowCollisions.ptr, 0, sizeof(NarrowCollision)*numNarrowCollisions[0]);
            std::memset(vertColFacets.ptr, 0, sizeof(NarrowCollision)*numNarrowCollisions[0]);
            std::memset(vertColFacetsOffsets.ptr, 0, sizeof(Index)*numNarrowCollisions[0]);
            numNarrowCollisions[0] = 0;
        }
    };
    inline static PackedCollisionData packedCollisionData;

    struct RayTracedData {
        VectorBase<BE, RayHit> clickRayCollisions;
        VectorBase<BE, Index> numClickRayCollisions;
        Index approxColsPerRay = 4096;
    };
    inline static RayTracedData rayTracedData;

    // Slice (c) — compact analytic-primitive array (A4). numAnalytic =
    // #meshes whose shapeType is Sphere/Cube/Cylinder. Allocated in
    // packAnalyticShapes() at pack; contents refilled by
    // refreshAnalyticShapes() each update (D3). No consumer in c-0.
    inline static VectorBase<BE, AnalyticShape> meshAnalytic;
    inline static Index numAnalytic = 0;

    static bool isPrimitiveShape(ShapeType s) {
        return s == ShapeType::Sphere
            || s == ShapeType::Cube
            || s == ShapeType::Cylinder;
    }

    // Refill meshAnalytic from the live mesh transform + initializer
    // intrinsic size. Iterates meshes in the SAME order as the count
    // pass so entry k always maps to the same mesh across frames.
    // v1 reads authoring transform (Q2: primitives static; Bullet-
    // driven motion reconciliation is c-4 / A9).
    static void refreshAnalyticShapes() {
        if (numAnalytic == 0 || !meshAnalytic.ptr) return;
        Index k = 0;
        for (Index i = 0; i < (Index)meshes.size(); ++i) {
            auto& m = meshes[i];
            if (!isPrimitiveShape(m.shapeType)) continue;

            // Intrinsic radius / half-extent (scale 1) from the
            // initializer; scaled into world units below. The analytic
            // sphere narrow path is an ELLIPSOID test, so per-axis
            // scale (+ rotQuat) is honoured via halfExtHeight; non-
            // uniform scale stretches the collision shape to match the
            // baked vertices. centerRadius.w stays the nominal (x-axis)
            // radius for any uniform-radius consumer.
            PR sz = PR(0);
            if (auto* sp = dynamic_cast<MeshSphereInitializer  <BE,PR>*>(m.initializer)) sz = sp->params.size;
            else if (auto* cb = dynamic_cast<MeshCubeInitializer    <BE,PR>*>(m.initializer)) sz = cb->params.size;
            else if (auto* cy = dynamic_cast<MeshCylinderInitializer<BE,PR>*>(m.initializer)) sz = cy->params.size;

            const tinym::vec3 c = m.transformPosition;
            const tinym::vec3 s = m.scale;
            // primitive::sphere/cube/cylinder build geometry with
            // r = size*0.5, so the world half-extent is size*0.5*scale.
            // (`sz` is the initializer's `size` = full diameter/edge.)
            const PR hsz = sz * PR(0.5);

            AnalyticShape a{};
            a.centerRadius  = tinym::vec4(c.x, c.y, c.z, (float)(hsz * s.x));
            a.halfExtHeight = tinym::vec4((float)(hsz * s.x),
                                          (float)(hsz * s.y),
                                          (float)(hsz * s.z),
                                          (float)(hsz * s.y));
            a.rotQuat       = tinym::vec4(m.rotationQuat.w, m.rotationQuat.x,
                                          m.rotationQuat.y, m.rotationQuat.z);
            a.prevCenterPad = tinym::vec4(c.x, c.y, c.z, 0.0f);
            a.shapeType     = (uint32_t)m.shapeType;
            a.objId         = (uint32_t)m.id;
            a.behaviorType  = (uint32_t)m.behaviorType;
            a.flags         = 1u; // bit0 = collidable
            meshAnalytic[k++] = a;
        }
    }

    // Count primitives, (re)allocate the compact buffer, fill it.
    // Called at the end of Scene::pack (size can change across packs).
    static void packAnalyticShapes() {
        Index count = 0;
        for (auto& m : meshes) if (isPrimitiveShape(m.shapeType)) ++count;
        numAnalytic = count;
        if (count == 0) { meshAnalytic = VectorBase<BE, AnalyticShape>(); return; }
        meshAnalytic = VectorBase<BE, AnalyticShape>(count);
        refreshAnalyticShapes();
    }

    static void pack() {
        if(!dirty) {
            initialize();
            return;
        }

        // meshes[i].initializer is the *same* pointer stored in
        // requestsGeneralMeshes[i].initializer (it was copied, not moved,
        // by addGeneralMesh + emplace_back). Without nulling here,
        // ~GeneralMesh would delete it, leaving requestsGeneralMeshes with
        // dangling pointers; the rebuild loop below would then dereference
        // freed memory. requestsGeneralMeshes is the canonical owner across
        // a re-pack; explicit delete only happens in loadScene.
        for (auto& m : meshes) m.initializer = nullptr;
        meshes.clear();

        // count sizes
        packedMeshData.statesOffsets = VectorBase<BE, Index>(numMeshes+1, 0);
        packedMeshData.facetsOffsets = VectorBase<BE, Index>(numMeshes+1, 0);
        packedMeshData.edgesOffsets  = VectorBase<BE, Index>(numMeshes+1, 0);
        std::vector<PR> masses(numMeshes);

        for(Index i = 0; i < requestsGeneralMeshes.size(); ++i) {
            RequestGeneralMesh& req = requestsGeneralMeshes[i];

            packedMeshData.statesOffsets[i+1] = packedMeshData.statesOffsets[i] + req.initializer->getParams()->numPoints;
            packedMeshData.facetsOffsets[i+1] = packedMeshData.facetsOffsets[i] + req.initializer->getParams()->numFacets;
            packedMeshData.edgesOffsets [i+1] = packedMeshData.edgesOffsets [i] + req.initializer->getParams()->numEdges;
            masses[i] = req.initializer->getParams()->mass;
        }

        // allocate MeshState
        Index numPoints = packedMeshData.statesOffsets[numMeshes];
        // Slice (c) A1: per-vertex owning mesh index. Each mesh i owns
        // the packed-vertex range [statesOffsets[i], statesOffsets[i+1]).
        packedMeshData.vertObj = VectorBase<BE, Index>(numPoints > 0 ? numPoints : 1, 0);
        for (Index i = 0; i < numMeshes; ++i)
            for (Index v = packedMeshData.statesOffsets[i];
                 v < packedMeshData.statesOffsets[i+1]; ++v)
                packedMeshData.vertObj[v] = i;
        Index numStatesData = numPoints*3;
        packedMeshData.x = VectorBase<BE, PR>(numStatesData);
        packedMeshData.xPrev = VectorBase<BE, PR>(numStatesData);
        packedMeshData.v = VectorBase<BE, PR>(numStatesData, 0);
        packedMeshData.f = VectorBase<BE, PR>(numStatesData, 0);
        packedMeshData.m = VectorBase<BE, PR>(numStatesData);
        for(Index i = 0; i < requestsGeneralMeshes.size(); ++i) 
            std::fill(packedMeshData.m.ptr + packedMeshData.statesOffsets[i]*3,
                    packedMeshData.m.ptr + packedMeshData.statesOffsets[i+1]*3,
                    masses[i]);
        packedMeshData.n = VectorBase<BE, PR>(numStatesData);
        packedMeshData.externalForces = VectorBase<BE, PR>(numStatesData, 0);

        // allocate MeshAdjacency
        packedMeshData.facets = VectorBase<BE, Index>(packedMeshData.facetsOffsets[numMeshes]*3);
        packedMeshData.edges  = VectorBase<BE, Index>(packedMeshData.edgesOffsets [numMeshes]*2);
        packedMeshData.vertexAdjFacetsOffsets = VectorBase<BE, Index>(numPoints+1, 0);
        packedMeshData.vertexAdjEdgesOffsets  = VectorBase<BE, Index>(numPoints+1, 0);

        // initialize meshes
        //meshes.resize(numMeshes);
        Index numVertexAdjFacets = 0, numVertexAdjEdges = 0;
        for(Index i = 0; i < numMeshes; ++i) {
            RequestGeneralMesh& req = requestsGeneralMeshes[i];
            meshes.emplace_back(req.initializer, req.behaviorType, req.behaviorParams);
            // pack is the single authoritative compaction point: id == the
            // request's array index i == this mesh's statesOffsets /
            // objTrees / faceObj subscript == objPair value. add/removeMesh
            // keep req.id == i too; writing it back here makes pack robust
            // to any caller (loadScene order, etc.) that didn't pre-compact.
            req.id = (int)i;
            meshes[i].id = (int)i;
            meshes[i].lifetimeId = req.lifetimeId;  // D-026
            // Carry per-mesh environment-force toggles through pack so
            // reset / load / changeBehavior rebuilds preserve the user's
            // Apply Gravity / Apply Wind selections.
            meshes[i].applyGravity = req.applyGravity;
            meshes[i].applyWind    = req.applyWind;
            meshes[i].isStatic     = req.isStatic;
            meshes[i].checkerboard = req.checkerboard;
            // Per-object sub-object BVH settings survive reset via the request.
            meshes[i].clusterSplitS = req.clusterSplitS;
            meshes[i].clusterRender = req.clusterRender;
            // Carry the user's orientation through pack. The R-3 preview
            // memcpy below restores the rotated *geometry*; this restores
            // the stored *quaternion* so the inspector keeps showing the
            // accumulated rotation and the next rotateObject composes its
            // delta against the true current orientation (not identity).
            meshes[i].rotationQuat = req.rotationQuat;
            // Same as rotationQuat: R-3's preview memcpy restores the
            // scaled geometry, this restores the stored scale factor so
            // the inspector keeps showing it and scaleObject composes its
            // next delta against the true current scale (not unit).
            meshes[i].scale = req.scale;
            meshes[i].clothStiffnessScale = req.clothStiffnessScale;
            // S3-2: material is request-owned; restore it onto the
            // rebuilt mesh (replaces the post-pack pendingMaterials
            // apply).
            meshes[i].material = req.material;
            // Seed transformPosition from the initializer's center/offset so
            // BDD-003's translate path computes deltas against the author
            // intent, not against (0,0,0). Mirrors the dynamic_cast cascade
            // in toSnapshot.
            // Also classifies shapeType from the initializer subtype in
            // the same pass ((a)+(b)). Set in EVERY branch (not relying
            // on the default) so a re-pack of a reused meshes[i] slot
            // can't carry a stale class. Grid/File stay Mesh — a grid
            // can be deforming cloth, so it is honestly mesh-collision;
            // analytic Plane is left for slice (c).
            if (auto* g  = dynamic_cast<MeshGridInitializer  <BE, PR>*>(req.initializer)) {
                meshes[i].transformPosition = g->params.center;
                meshes[i].shapeType = ShapeType::Mesh;
            } else if (auto* sp = dynamic_cast<MeshSphereInitializer<BE, PR>*>(req.initializer)) {
                meshes[i].transformPosition = sp->params.center;
                meshes[i].shapeType = ShapeType::Sphere;
            } else if (auto* cb = dynamic_cast<MeshCubeInitializer  <BE, PR>*>(req.initializer)) {
                meshes[i].transformPosition = cb->params.center;
                meshes[i].shapeType = ShapeType::Cube;
            } else if (auto* cy = dynamic_cast<MeshCylinderInitializer<BE, PR>*>(req.initializer)) {
                meshes[i].transformPosition = cy->params.center;
                meshes[i].shapeType = ShapeType::Cylinder;
            } else if (auto* kb = dynamic_cast<MeshKinematicInitializer<BE, PR>*>(req.initializer)) {
                meshes[i].transformPosition = kb->params.center;
                meshes[i].shapeType = ShapeType::Mesh;
            } else if (auto* f  = dynamic_cast<MeshFileInitializer  <BE, PR>*>(req.initializer)) {
                meshes[i].transformPosition = f->params.offset;
                meshes[i].shapeType = ShapeType::Mesh;
            } else if (auto* a  = dynamic_cast<AssimpMeshFileInitializer<BE, PR>*>(req.initializer)) {
                // AssimpMeshFileInitializer is a SIBLING of MeshFileInitializer
                // (both derive from GeneralMeshInitializer), so the cast above
                // does not match it. Without this branch a re-pack on reset
                // reseeds transformPosition to (0,0,0) and drops imported-mesh
                // position.
                meshes[i].transformPosition = a->params.offset;
                meshes[i].shapeType = ShapeType::Mesh;
            } else {
                meshes[i].shapeType = ShapeType::Mesh;
            }
            Index prevNumPoints = packedMeshData.statesOffsets[i];
            Index curNumPoints = packedMeshData.statesOffsets[i+1]-prevNumPoints;
            meshes[i].state.x = VectorBase<BE, PR>(packedMeshData.x, prevNumPoints*3, curNumPoints*3);
            meshes[i].state.xPrev = VectorBase<BE, PR>(packedMeshData.xPrev, prevNumPoints*3, curNumPoints*3);
            meshes[i].state.v = VectorBase<BE, PR>(packedMeshData.v, prevNumPoints*3, curNumPoints*3);
            meshes[i].state.f = VectorBase<BE, PR>(packedMeshData.f, prevNumPoints*3, curNumPoints*3);
            meshes[i].state.m = VectorBase<BE, PR>(packedMeshData.m, prevNumPoints*3, curNumPoints*3);
            meshes[i].state.n = VectorBase<BE, PR>(packedMeshData.n, prevNumPoints*3, curNumPoints*3);
            meshes[i].externalForces.externalForces = VectorBase<BE, PR>(packedMeshData.externalForces, prevNumPoints*3, curNumPoints*3);

            meshes[i].adjacency.facets = VectorBase<BE, Index>(packedMeshData.facets, packedMeshData.facetsOffsets[i]*3, (packedMeshData.facetsOffsets[i+1]-packedMeshData.facetsOffsets[i])*3);
            meshes[i].adjacency.edges  = VectorBase<BE, Index>(packedMeshData.edges, packedMeshData.edgesOffsets[i]*2, (packedMeshData.edgesOffsets[i+1]-packedMeshData.edgesOffsets[i])*2);

            meshes[i].initialize();

            // S3-3: pack rebuilds the FULL transformed geometry
            // deterministically from the request alone — no preview
            // carrier. mesh.initialize() above produced the base shape
            // + topology at `center`; bake the request's transform in
            // place over state.x: scale → rotate → translate, pivot =
            // transformPosition (== the initializer center, set just
            // above). Topology (adjacency.facets) and base normals came
            // from the initializer regen and are correct; rotation also
            // rotates the normals so a paused mesh lights correctly
            // pre-sim. Replaces the D-042 R-3 preview→state override.
            {
                const tinym::vec3 pivot = meshes[i].transformPosition;
                auto* ip = req.initializer->getParams();
                const tinym::vec3 s = ip->scale;
                const ::Quat q = ip->rotationQuat;
                const bool unitS = std::abs(s.x-1.f)<1e-7f
                                && std::abs(s.y-1.f)<1e-7f
                                && std::abs(s.z-1.f)<1e-7f;
                const bool idQ = std::abs(q.w-1.f)<1e-7f
                              && std::abs(q.x)<1e-7f
                              && std::abs(q.y)<1e-7f
                              && std::abs(q.z)<1e-7f;
                if (!unitS || !idQ) {
                    const size_t nP = (size_t)curNumPoints;
                    PR* xs = meshes[i].state.x.ptr;
                    PR* ns = meshes[i].state.n.ptr;
                    for (size_t v = 0; v < nP; ++v) {
                        tinym::vec3 p(xs[v*3+0], xs[v*3+1], xs[v*3+2]);
                        tinym::vec3 d = p - pivot;
                        d = tinym::vec3(d.x*s.x, d.y*s.y, d.z*s.z);
                        if (!idQ) d = rotateVector(q, d);
                        xs[v*3+0] = (PR)(pivot.x + d.x);
                        xs[v*3+1] = (PR)(pivot.y + d.y);
                        xs[v*3+2] = (PR)(pivot.z + d.z);
                        if (ns && !idQ) {
                            tinym::vec3 nv = rotateVector(q,
                                tinym::vec3(ns[v*3+0], ns[v*3+1], ns[v*3+2]));
                            ns[v*3+0] = (PR)nv.x;
                            ns[v*3+1] = (PR)nv.y;
                            ns[v*3+2] = (PR)nv.z;
                        }
                    }
                }
            }

            // Behavior-driven cloth jiggle. state.x currently holds the
            // flat preview (R-3 memcpy above). If THIS mesh is currently
            // a cloth, perturb it sub-visibly so the solver/narrow-phase
            // isn't degenerate on a perfectly coplanar sheet; if it is
            // Rigid (or anything non-cloth) leave it flat. Reseeded from
            // the stable mesh id each pack and always run on the just-
            // memcpy'd FLAT buffer, so toggling Rigid<->Cloth back and
            // forth reproduces the identical cloth state every time with
            // zero accumulation. Runs BEFORE recomputeRestLengths so the
            // rest config is measured from the jiggled (== simulated)
            // geometry — keeps the "rest length == what is simulated"
            // invariant intact.
            {
                bool isCloth =
                    meshes[i].behaviorType == BehaviorType::TriangularCloth
                 || meshes[i].behaviorType == BehaviorType::FastGridCloth;
                if (isCloth) {
                    if (auto* g = dynamic_cast<MeshGridInitializer<BE, PR>*>(
                            req.initializer)) {
                        g->applyClothJiggle(meshes[i].state.x.ptr,
                                            curNumPoints,
                                            (uint32_t)meshes[i].id);
                    }
                }
            }

            // Rest length must reflect the geometry the user sees (the
            // preview just memcpy'd into state.x), NOT the initializer's
            // param-regen that mesh.initialize() measured a few lines up.
            // Without this, scale/rotate edits (preview-only mutations)
            // leave every cloth spring pre-stressed → free-fall blow-up.
            // (When cloth, "what the user sees" includes the <=1e-4
            // jiggle applied just above — invisible but consistent.)
            MeshAdjacencyInitializer<BE, PR>::recomputeRestLengths(
                meshes[i].state, meshes[i].adjacency);

            // recomputeRestLengths only fixes the adjacency arrays
            // (TriangularCloth). FastGridCloth's solver instead reads
            // the scalar rest lengths in its behavior params, so a
            // scaled/rotated grid would stay pre-stressed without this.
            // state.x here is the fully transformed geometry, so derive
            // the scalars from it and keep the request copy in lock-step
            // (a later non-dirty re-pack reuses req.behaviorParams).
            if (meshes[i].behaviorType == BehaviorType::FastGridCloth) {
                if (auto* fp = std::get_if<FastGridClothBehaviorParams<PR>>(
                        &meshes[i].behaviorParams)) {
                    recomputeFastGridRest<PR>(meshes[i].state.x.ptr,
                                              meshes[i].state.x.size / 3,
                                              *fp);
                    req.behaviorParams = meshes[i].behaviorParams;
                }
            }

            // Seed xPrev with the initial position so the first substep's
            // swept-CCD narrow check (D-013) sees a degenerate segment
            // (xPrev == x) rather than dangling zeros, which would
            // otherwise trigger spurious crossings. Sits AFTER the R-3
            // memcpy so xPrev mirrors the post-preview x (not the
            // initializer's pre-override regen).
            std::memcpy(meshes[i].state.xPrev.ptr,
                        meshes[i].state.x.ptr,
                        meshes[i].state.x.size * sizeof(PR));

            // Re-apply pinned-vertex constraints from the request (the
            // source of truth). Runs LAST so the pinned position wins
            // over preview/jiggle/recompute: write the held position
            // into state.x + xPrev, set the fixedParticles mask to 0,
            // and mirror into preview (physics + any render copies) so
            // the rendered dot + the next pack's R-3 memcpy agree. This
            // is what makes a pin survive Scene::pack AND loadScene
            // (loadScene rebuilds preview flat from the initializer; the
            // request list restores both the pin and its location).
            for (const auto& fv : req.fixedVertices) {
                if ((Index)fv.vid >= (Index)curNumPoints) continue;
                Index b = (Index)fv.vid * 3;
                meshes[i].state.x.ptr[b+0] = (PR)fv.pos.x;
                meshes[i].state.x.ptr[b+1] = (PR)fv.pos.y;
                meshes[i].state.x.ptr[b+2] = (PR)fv.pos.z;
                meshes[i].state.xPrev.ptr[b+0] = (PR)fv.pos.x;
                meshes[i].state.xPrev.ptr[b+1] = (PR)fv.pos.y;
                meshes[i].state.xPrev.ptr[b+2] = (PR)fv.pos.z;
                if (meshes[i].constraints.fixedParticles.ptr
                    && (Index)fv.vid < meshes[i].constraints.fixedParticles.size)
                    meshes[i].constraints.fixedParticles[fv.vid] = PR(0);
                if (fv.vid * 3 + 2 < req.preview.x.size()) {
                    req.preview.x[b+0] = (PR)fv.pos.x;
                    req.preview.x[b+1] = (PR)fv.pos.y;
                    req.preview.x[b+2] = (PR)fv.pos.z;
                }
                if (req.preview.hasRender()) {
                    for (size_t rv = 0; rv < req.preview.renderToPhysics.size(); ++rv)
                        if (req.preview.renderToPhysics[rv] == fv.vid) {
                            req.preview.renderX[rv*3+0] = (PR)fv.pos.x;
                            req.preview.renderX[rv*3+1] = (PR)fv.pos.y;
                            req.preview.renderX[rv*3+2] = (PR)fv.pos.z;
                        }
                }
            }

            for(int j = 0; j < curNumPoints; ++j) {
                packedMeshData.vertexAdjFacetsOffsets[prevNumPoints+j+1] = meshes[i].adjacency.vertexAdjFacetsOffsets[j+1]+numVertexAdjFacets;
                packedMeshData.vertexAdjEdgesOffsets [prevNumPoints+j+1] = meshes[i].adjacency.vertexAdjEdgesOffsets [j+1]+numVertexAdjEdges;
            }
            numVertexAdjFacets += meshes[i].adjacency.vertexAdjFacets.size;
            numVertexAdjEdges  += meshes[i].adjacency.vertexAdjEdges.size;
        }

        packedMeshData.vertexAdjFacets = VectorBase<BE, Index>(numVertexAdjFacets);
        packedMeshData.vertexAdjEdges  = VectorBase<BE, Index>(numVertexAdjEdges);
        numVertexAdjFacets = numVertexAdjEdges = 0;
        Index numFacets = 0, numEdges = 0;
        for(Index i = 0; i < numMeshes; ++i) {
            auto& vaf = meshes[i].adjacency.vertexAdjFacets;
            auto& vae = meshes[i].adjacency.vertexAdjEdges;
            std::copy(vaf.ptr, vaf.ptr+vaf.size, packedMeshData.vertexAdjFacets.ptr+numVertexAdjFacets);
            std::copy(vae.ptr, vae.ptr+vae.size, packedMeshData.vertexAdjEdges.ptr+numVertexAdjEdges);
            for(Index j = 0; j < vaf.size; ++j)
                if(packedMeshData.vertexAdjFacets[numVertexAdjFacets+j] != vaf[j]) exit(1);
            for(Index j = 0; j < vae.size; ++j)
                if(packedMeshData.vertexAdjEdges[numVertexAdjEdges+j]  != vae[j]) exit(1);
            vaf = VectorBase<BE, Index>(packedMeshData.vertexAdjFacets, numVertexAdjFacets, vaf.size);
            vae = VectorBase<BE, Index>(packedMeshData.vertexAdjEdges,  numVertexAdjEdges,  vae.size);
            numVertexAdjFacets += vaf.size;
            numVertexAdjEdges  += vae.size;
        }

        // allocate collisions
        // YSIM_COLS_PER_POINT raises the per-point broad-pair budget so a
        // densely-draping cloth on a big obstacle (P200 + camel ≈ 6–12M
        // pairs) does NOT overflow the buffer and silently drop pairs —
        // dropped pairs are the source of non-reproducible detect times and
        // patchy tunneling. Default 15 keeps normal-run memory small.
        if (const char* e = std::getenv("YSIM_COLS_PER_POINT")) {
            int v = std::atoi(e);
            if (v > 0) packedCollisionData.approxColsPerPoints = (Index)v;
        }
        packedCollisionData.maxNumCollisions = numPoints*packedCollisionData.approxColsPerPoints;
        packedCollisionData.broadCollisions = VectorBase<BE, BroadCollision>(packedCollisionData.maxNumCollisions);
        packedCollisionData.numBroadCollisions = VectorBase<BE, Index>(1, 0);
        packedCollisionData.narrowCollisions = VectorBase<BE, NarrowCollision>(packedCollisionData.maxNumCollisions);
        packedCollisionData.numNarrowCollisions = VectorBase<BE, Index>(1, 0);
        packedCollisionData.vertColFacets = VectorBase<BE, NarrowCollision>(packedCollisionData.maxNumCollisions);
        packedCollisionData.vertColFacetsOffsets = VectorBase<BE, Index>(numPoints+1, 0);
        packedCollisionData.vertColBucketCounter = VectorBase<BE, Index>(numPoints, 0);

        // Segmented variant scratch (paper-inspired alternative path).
        // Sized so a single queryPointsSegmented dispatch over ANY mesh
        // fits: segMaxTGs uses TOTAL numPoints as an upper bound on any
        // single mesh's point count, segPerTGCap mirrors the global
        // per-point estimate scaled to one threadgroup.
        // Decoupled from approxColsPerPoints: the segmented path's per-TG
        // budget keeps its historical base (15) so raising the global broad
        // budget (YSIM_COLS_PER_POINT) does not multiply this scratch by the
        // same factor (would balloon to ~1GB at cols=256). Segmented query is
        // off in the cluster bench anyway; this only sizes its idle scratch.
        packedCollisionData.segPerTGCap = Index(15)
                                        * packedCollisionData.segTGSize
                                        * packedCollisionData.segPerTGCapFactor;
        packedCollisionData.segMaxTGs   = std::max<Index>(1,
            (numPoints + packedCollisionData.segTGSize - 1) / packedCollisionData.segTGSize);
        packedCollisionData.segPrivateCollisions = VectorBase<BE, BroadCollision>(
            packedCollisionData.segMaxTGs * packedCollisionData.segPerTGCap);
        packedCollisionData.segPrivateCount  = VectorBase<BE, uint32_t>(packedCollisionData.segMaxTGs, 0);
        packedCollisionData.segPrivateOffset = VectorBase<BE, uint32_t>(packedCollisionData.segMaxTGs, 0);


        // allocate ray traced data
        rayTracedData.clickRayCollisions = VectorBase<BE, RayHit>(rayTracedData.approxColsPerRay);
        rayTracedData.numClickRayCollisions = VectorBase<BE, Index>(1, 0);


        // adjacency data

        // Slice (c) c-0: build the compact analytic-primitive array
        // from the now-realized meshes (shapeType/transform set by the
        // cascade above). Inert — no kernel consumes it yet.
        packAnalyticShapes();

        dirty = false;
    }

    static void initialize() {
        for(auto& mesh : meshes) {
            std::cout << "  - try to initialize mesh " << mesh.id << "\n";
            mesh.initialize();
            mesh.state.v.map().setZero();
            std::cout << "  - mesh " << mesh.id << " is initialized\n";
        }
        if(meshes.size() > 0) std::cout << "[Simulator Init] general mesh objects are initialized" << std::endl;
    }

    /// postpack() is for data which is able to allocate after the mesh initialization.



    static GeneralMesh<BE, PR>* findById(int id) {
        for(auto& mesh : meshes) {
            if(mesh.id == id) return &mesh;
        }
        return nullptr;
    }
};



// RadixSorter is declared here (above SpatialHashing) so that
// SpatialHashing<METAL, PR> can hold a value-typed RadixSorter member.
// The primary template and METAL specialization were originally further
// down the file alongside BVH; they were moved up unchanged.
template <typename BE, typename Element>
struct RadixSorter {};

template <typename Element>
struct RadixSorter<METAL, Element> {
    uint32_t BITS_PER_PASS = 8;
    uint32_t NUM_BUCKETS = 1 << BITS_PER_PASS;
    uint32_t BLOCK_SIZE = 1024; // range limit: 256-1024
    VectorBase<METAL, Element> dst;
    VectorBase<METAL, Index> blockHist; // NumBlocks * 2^{BITS_PER_PASS}
    VectorBase<METAL, Index> hist; // 2^{BITS_PER_PASS}
    VectorBase<METAL, Index> blockOffset; // NumBlocks * 2^{BITS_PER_PASS}

    MTL::ComputePipelineState* radixCountBlockPSO;
    MTL::ComputePipelineState* radixScanOffsetPSO;
    MTL::ComputePipelineState* radixScatterPSO;


    struct RadixParams {
        uint numBlocks;
        uint numElements;
        uint blockSize;
        uint shift;
    };

    inline uint32_t getNumBlocks(const VectorBase<METAL, Element>& src) {
        return (src.size + BLOCK_SIZE - 1) / BLOCK_SIZE;
    }

    RadixSorter() {
        radixCountBlockPSO = MetalKernelContext::getPSO("radixCountBlock_8Bits");
        radixScanOffsetPSO = MetalKernelContext::getPSO("radixScanOffset_8Bits");
        radixScatterPSO = MetalKernelContext::getPSO("radixScatter_8Bits");
    }

    inline void memoryAllocation(const VectorBase<METAL, Element>& src) {
        uint32_t numBlocks = getNumBlocks(src);
        if(!dst.ptr || dst.size < src.size) dst = VectorBase<METAL, Element>(src.size);
        if(!hist.ptr || hist.size < NUM_BUCKETS) hist = VectorBase<METAL, Index>(NUM_BUCKETS);
        if(!blockHist.ptr || blockHist.size < NUM_BUCKETS*numBlocks) blockHist = VectorBase<METAL, Index>(NUM_BUCKETS*numBlocks);
        if(!blockOffset.ptr || blockOffset.size < NUM_BUCKETS*numBlocks) blockOffset = VectorBase<METAL, Index>(NUM_BUCKETS*numBlocks);
    }
    void sort(VectorBase<METAL, Element>& src) {
        memoryAllocation(src);

        RadixParams params;
        params.numBlocks = getNumBlocks(src);
        params.numElements = src.size;
        params.blockSize = BLOCK_SIZE;
        for(uint32_t r = 0; r < 32; r+=BITS_PER_PASS) {
            params.shift = r;
            MetalGlobalContext::setBuffer(src, 0);
            MetalGlobalContext::setBuffer(blockHist, 1);
            MetalGlobalContext::setBytes(params, 2);
            MetalGlobalContext::setBuffer(hist, 3);
            MetalGlobalContext::setBuffer(blockOffset, 4);
            MetalGlobalContext::setBuffer(dst, 5);

            MetalGlobalContext::dispatchThreads(radixCountBlockPSO, params.numBlocks*BLOCK_SIZE, BLOCK_SIZE);
            MetalGlobalContext::dispatchThreads(radixScanOffsetPSO, NUM_BUCKETS, NUM_BUCKETS);
            MetalGlobalContext::dispatchThreads(radixScatterPSO, params.numBlocks*BLOCK_SIZE, BLOCK_SIZE);

            std::swap(src, dst);
        }
    }
};


// TODO: BroadPhase, SpatialHashing
template <typename BE, typename PR>
struct SpatialHashing {};

// Spatial-hashing broadphase (Pabst-style uniform-grid) for the METAL backend.
//
// Implemented step-by-step alongside the existing BVH broadphase; both share
// the BroadCollision output convention so the rest of the pipeline
// (narrow_pt_tri, narrowAndSortByVertices) is unchanged.
//
// Surface mirrors BVH<METAL, PR, BVHMODE::SCENE, BVHPRIMITIVE::OBJECT> so the
// `Simulator::BroadPhase` typedef can be swapped at compile time. All methods
// in Step 0 are no-ops; later steps fill them in.
//
// Pipeline (target end state):
//   1. per-triangle bounding sphere (centroid, radius)         [Step 1]
//   2. max-radius reduction -> cellSize                        [Step 2]
//   3. scene AABB + grid resolution (host)                     [Step 3]
//   4. cell assignment (home + up to 7 phantoms per face)      [Step 4]
//   5. radix sort entries by cellID                            [Step 5]
//   6. cell ranges + nH/nP per cell                            [Step 6]
//   7. pair-count + prefix sum -> P (#candidate pairs)         [Step 7]
//   8. per-pair broad-phase -> BroadCollision[6 per tri pair]  [Step 8]
template<typename PR>
struct SpatialHashing<METAL, PR> {
    // Host-side mirror of metal's SHParams. Layout must match exactly because
    // setBytes copies raw bytes to constant memory.
    struct SHParamsHost {
        uint32_t numFaces;
        float    cellSize;
        float    epsilon;
        uint32_t gridRes[3];     // packed_uint3 = 3 contiguous uints
        float    originMin[3];   // packed_float3 = 3 contiguous floats
    };
    static_assert(sizeof(SHParamsHost) == 36,
                  "SHParamsHost must match metal SHParams layout (36 bytes)");

    // 8-byte hash-table entry, layout-compatible with SortPair so the radix
    // sorter (Step 5) can swap it directly. cellID == 0xFFFFFFFF marks an
    // unused slot and sorts to the tail.
    struct SHEntry {
        uint32_t cellID;
        uint32_t value;
    };
    static_assert(sizeof(SHEntry) == 8, "SHEntry must be 8 bytes");

    // ----- Buffers (allocated lazily; Step 0 leaves them empty) -----
    VectorBase<METAL, PR>          centroid;             // 3*m floats, packed_float3
    VectorBase<METAL, PR>          radius;               // m
    VectorBase<METAL, PR>          maxRadius;            // 1
    VectorBase<METAL, PR>          radiusReducePartial;  // ceil(m/256)
    VectorBase<METAL, PR>          radiusReducePartial2; // ceil(m/256/256), ping-pong
    VectorBase<METAL, Index>       faceObj;              // m, owning object id per global face
    VectorBase<METAL, uint32_t>    meshBehaviors;        // numMeshes, BehaviorType per mesh
    VectorBase<METAL, uint32_t>    meshShapes;           // numMeshes, ShapeType per mesh
    VectorBase<METAL, uint8_t>     faceCB;               // m, 8-bit cell-type bitmask
    VectorBase<METAL, SHEntry>     entries;              // m*8, cellID=0xFFFFFFFF sentinel
    VectorBase<METAL, uint32_t>    cellStartFlag;        // m*8, 1 if entry starts a new cell
    VectorBase<METAL, uint32_t>    cellStartScan;        // m*8, exclusive scan of cellStartFlag
    // CellProp lives in metal-side struct; on host we mirror it as 5 uints.
    struct CellPropHost {
        uint32_t start;
        uint32_t nH;
        uint32_t nP;
        uint32_t pairCnt;
        uint32_t cellType;
    };
    VectorBase<METAL, CellPropHost> cellProp;            // C entries
    VectorBase<METAL, uint32_t>    pairPrefix;           // C+1, last = P
    VectorBase<METAL, uint32_t>    numCellsBuf;          // 1
    VectorBase<METAL, uint32_t>    numCandidatePairsBuf; // 1
    // sceneBox is small POD; passed via setBytes at Step 3 (no buffer needed).

    // ----- PSO handles (looked up per step as kernels are added) -----
    // Step 1+ will populate these; Step 0 keeps them null.
    MTL::ComputePipelineState* buildBVPSO          = nullptr;
    MTL::ComputePipelineState* reduceMaxRadiusPSO  = nullptr;
    MTL::ComputePipelineState* reduceFinalPSO      = nullptr;
    MTL::ComputePipelineState* assignCellsPSO      = nullptr;
    MTL::ComputePipelineState* markStartsPSO       = nullptr;
    MTL::ComputePipelineState* fillCellPropPSO     = nullptr;
    MTL::ComputePipelineState* computePairCountPSO = nullptr;
    MTL::ComputePipelineState* broadPhasePSO       = nullptr;

    // ----- Scene context cached at build() time -----
    Scene<METAL, PR>* scenePtr = nullptr;
    Index numFaces = 0;
    Index numValidEntries = 0;   // populated after Step 5 (radix sort + scan)
    Index numCells = 0;          // populated after Step 6 (mark + scan + fill)
    Index numCandidatePairs = 0; // populated after Step 7 (pair-count + scan)

    // Reused 4-pass 8-bit radix sorter from RadixSorter<METAL, MortonNode>;
    // SHEntry has the same {uint key=cellID, uint value} byte layout, so the
    // metal kernels work without modification.
    RadixSorter<METAL, SHEntry> sorter;

    // Filled in detectCollisions() once per frame; consumed by Steps 4+ via
    // setBytes. Matches metal SHParams layout exactly (36 bytes).
    SHParamsHost params{};

    // Optional. If non-null, detectCollisions() emits sh_* timing sections
    // that line up with the existing bvh_* labels for side-by-side compare.
    profiler::FrameProfiler* profiler = nullptr;

    // Per-stage timings + workload counters from the most recent
    // detectCollisions(). Filled every call (cheap), so the simulator can dump
    // a one-line log per substep without extra GPU work.  Note: when `verbose`
    // is false, `ms_broad` only times the dispatch (no commit) and `numBroadOut`
    // is whatever was visible at the last commitAndWait inside the pipeline.
    struct LastRunStats {
        Index  numFaces        = 0;
        Index  numValidEntries = 0;
        Index  numCells        = 0;
        Index  numCandidatePairs = 0;
        Index  numBroadOut     = 0;
        Index  maxNH           = 0;
        Index  maxNP           = 0;
        Index  maxPairCnt      = 0;
        Index  numPoints       = 0;
        float    cellSize      = 0.f;
        float    maxRadius     = 0.f;
        float    extent[3]     = {0.f, 0.f, 0.f};
        float    aabbMin[3]    = {0.f, 0.f, 0.f};
        uint32_t gridRes[3]    = {0, 0, 0};
        double ms_buildBV    = 0.0;
        double ms_reduce     = 0.0;
        double ms_grid       = 0.0;
        double ms_assign     = 0.0;
        double ms_sort       = 0.0;
        double ms_cellprop   = 0.0;
        double ms_pairprefix = 0.0;
        double ms_broad      = 0.0;
        double ms_total      = 0.0;
    };
    LastRunStats lastStats{};

    // When true, detectCollisions() commits after the broad-phase dispatch so
    // ms_broad and numBroadOut reflect actual GPU work (instead of just the
    // dispatch cost). Adds a sync point — keep off in steady-state.
    bool verbose = false;

    // Multiplier on the Pabst cell-size rule: cellSize = 2·maxRadius·factor + margin.
    //   factor = 1.0 (default): exact Pabst rule. Every face's BV fits in a
    //                            2x2x2 home+phantom cluster, so the 8 entry
    //                            slots/face in sh_assignCells are sufficient.
    //   factor < 1.0           : finer grid, but a face's BV may now span more
    //                            than 2 cells per axis. The current
    //                            sh_assignCells only emits 8 cells/face, so
    //                            some overlapped cells will be missed and the
    //                            large BVs lose collision pairs. Useful as a
    //                            quick experiment to see whether finer cells
    //                            relieve a hot cell; if it helps materially,
    //                            widen the slot budget and switch to the
    //                            general gMin..gMax cell-range assignment.
    //   factor > 1.0           : coarser grid, slot budget remains safe.
    float cellSizeFactor = 1.0f;

    SpatialHashing() = default;

    void memoryAllocation() {
        if (numFaces == 0) return;
        if (centroid.ptr && centroid.size == numFaces * 3) return;
        centroid = VectorBase<METAL, PR>(numFaces * 3);
        radius   = VectorBase<METAL, PR>(numFaces);

        constexpr Index TG = 256;
        Index ng1 = (numFaces + TG - 1) / TG;
        Index ng2 = std::max<Index>((ng1 + TG - 1) / TG, 1);
        radiusReducePartial  = VectorBase<METAL, PR>(std::max<Index>(ng1, 1));
        radiusReducePartial2 = VectorBase<METAL, PR>(ng2);
        if (!maxRadius.ptr) maxRadius = VectorBase<METAL, PR>(1);

        entries = VectorBase<METAL, SHEntry>(numFaces * 8);
        faceCB  = VectorBase<METAL, uint8_t>(numFaces);

        cellStartFlag = VectorBase<METAL, uint32_t>(numFaces * 8);
        cellStartScan = VectorBase<METAL, uint32_t>(numFaces * 8);
    }

    // faceObj[gFace] = owning object id. Walks facetsOffsets once; only
    // rebuilt when scene size changes.
    void rebuildFaceObj() {
        if (!scenePtr) return;
        auto& packed = Scene<METAL, PR>::packedMeshData;
        Index m = packed.facets.size / 3;
        if (faceObj.ptr && faceObj.size == m) return;
        faceObj = VectorBase<METAL, Index>(m);
        Index numMeshes = Scene<METAL, PR>::numMeshes;
        for (Index obj = 0; obj < numMeshes; ++obj) {
            Index begin = packed.facetsOffsets[obj];
            Index end   = packed.facetsOffsets[obj + 1];
            for (Index f = begin; f < end; ++f) faceObj[f] = obj;
        }
    }

    // meshBehaviors[obj] / meshShapes[obj] mirror the per-mesh enums into
    // GPU-readable arrays. Step 8 reads them per pair.
    void rebuildMeshKinds() {
        Index numMeshes = Scene<METAL, PR>::numMeshes;
        if (meshBehaviors.ptr && meshBehaviors.size == numMeshes) return;
        meshBehaviors = VectorBase<METAL, uint32_t>(numMeshes);
        meshShapes    = VectorBase<METAL, uint32_t>(numMeshes);
        auto& meshes = Scene<METAL, PR>::meshes;
        for (Index i = 0; i < numMeshes; ++i) {
            meshBehaviors[i] = (uint32_t)meshes[i].behaviorType;
            meshShapes[i]    = (uint32_t)meshes[i].shapeType;
        }
    }

    // Match BVH<SCENE,OBJECT> surface so CollisionPipeline / Simulator can
    // typedef to either implementation.
    void build(Scene<METAL, PR>& scene) {
        scenePtr = &scene;
        auto& packed = Scene<METAL, PR>::packedMeshData;
        numFaces = packed.facets.size / 3;
        rebuildFaceObj();
        rebuildMeshKinds();
        memoryAllocation();
        if (!buildBVPSO)         buildBVPSO         = MetalKernelContext::getPSO("sh_buildBV");
        if (!reduceMaxRadiusPSO) reduceMaxRadiusPSO = MetalKernelContext::getPSO("sh_reduceMaxRadius");
        if (!assignCellsPSO)     assignCellsPSO     = MetalKernelContext::getPSO("sh_assignCells");
        if (!markStartsPSO)      markStartsPSO      = MetalKernelContext::getPSO("sh_markStarts");
        if (!fillCellPropPSO)    fillCellPropPSO    = MetalKernelContext::getPSO("sh_fillCellProp");
        if (!computePairCountPSO)computePairCountPSO= MetalKernelContext::getPSO("sh_computePairCount");
        if (!broadPhasePSO)      broadPhasePSO      = MetalKernelContext::getPSO("sh_broadPhase");
    }

    // Step 1 dispatch. Uses `params` (filled by computeGrid in Step 3); only
    // params.numFaces matters to sh_buildBV but we set the whole struct so
    // the same layout flows into later stages.
    void runBuildBV() {
        if (numFaces == 0 || !buildBVPSO) return;
        auto& packed = Scene<METAL, PR>::packedMeshData;
        params.numFaces = (uint32_t)numFaces;

        MetalGlobalContext::setBuffer(packed.x, 0);
        MetalGlobalContext::setBuffer(packed.statesOffsets, 1);
        MetalGlobalContext::setBuffer(packed.facets, 2);
        MetalGlobalContext::setBuffer(faceObj, 3);
        MetalGlobalContext::setBytes(params, 4);
        MetalGlobalContext::setBuffer(centroid, 5);
        MetalGlobalContext::setBuffer(radius, 6);
        MetalGlobalContext::dispatchThreads(buildBVPSO, numFaces);
    }

    // Iteratively reduce `radius[numFaces]` to a single max in `maxRadius[0]`.
    // Each pass reduces by a factor of 256 (threadgroup size). Output buffer
    // alternates between `radiusReducePartial` / `radiusReducePartial2`; the
    // pass that brings count down to 1 writes directly to `maxRadius`.
    void runReduceMaxRadius() {
        if (numFaces == 0 || !reduceMaxRadiusPSO) return;
        constexpr Index TG = 256;

        auto dispatch = [&](VectorBase<METAL, PR>& in,
                            VectorBase<METAL, PR>& out,
                            uint32_t cnt) {
            Index ng = (cnt + TG - 1) / TG;
            MetalGlobalContext::setBuffer(in, 0);
            MetalGlobalContext::setBuffer(out, 1);
            MetalGlobalContext::setBytes(cnt, 2);
            MetalGlobalContext::dispatchThreads(reduceMaxRadiusPSO, ng * TG, TG);
            return ng;
        };

        // Pass 1: radius -> partial (or maxRadius if it already fits in one group).
        uint32_t cnt = (uint32_t)numFaces;
        Index ng = (cnt + TG - 1) / TG;
        VectorBase<METAL, PR>* dst = (ng == 1) ? &maxRadius : &radiusReducePartial;
        dispatch(radius, *dst, cnt);

        // Subsequent passes: ping-pong until we drive count to 1.
        VectorBase<METAL, PR>* src = dst;
        VectorBase<METAL, PR>* alt = (src == &radiusReducePartial)
                                     ? &radiusReducePartial2
                                     : &radiusReducePartial;
        while (ng > 1) {
            cnt = (uint32_t)ng;
            Index ng2 = (cnt + TG - 1) / TG;
            VectorBase<METAL, PR>* nextDst = (ng2 == 1) ? &maxRadius : alt;
            dispatch(*src, *nextDst, cnt);
            ng = ng2;
            src = nextDst;
            alt = (alt == &radiusReducePartial) ? &radiusReducePartial2
                                                : &radiusReducePartial;
        }
    }

    // ----- Step 3: scene AABB + grid resolution (host-side) -----
    //
    // CPU scan over packedMeshData.x to compute scene min/max, then derive
    // cellSize and per-axis gridRes. Result is stashed into `params` so the
    // same struct flows into all subsequent kernel dispatches via setBytes.
    //
    // Caller must ensure GPU writes to packedMeshData.x and maxRadius[0]
    // have completed (commitAndWait) before this runs.
    void computeGrid(PR margin) {
        if (numFaces == 0) return;
        auto& packed = Scene<METAL, PR>::packedMeshData;
        Index numMeshes = Scene<METAL, PR>::numMeshes;
        // Walk via statesOffsets so the per-mesh range is explicit. Equivalent
        // to (0 .. packed.x.size/3) when the scene is well-packed, but makes
        // any offset/coverage bug observable.
        Index totalPoints = (numMeshes > 0) ? packed.statesOffsets[numMeshes] : 0;
        if (totalPoints == 0) return;

        tinym::vec3 mn(packed.x.ptr[0], packed.x.ptr[1], packed.x.ptr[2]);
        tinym::vec3 mx = mn;
        Index visited = 0;
        for (Index obj = 0; obj < numMeshes; ++obj) {
            Index begin = packed.statesOffsets[obj];
            Index end   = packed.statesOffsets[obj + 1];
            for (Index v = begin; v < end; ++v) {
                tinym::vec3 p(packed.x.ptr[v*3 + 0],
                              packed.x.ptr[v*3 + 1],
                              packed.x.ptr[v*3 + 2]);
                mn = tinym::min(mn, p);
                mx = tinym::max(mx, p);
            }
            visited += (end - begin);
        }
        // Sanity: every vertex was visited and the buffer holds nothing extra.
        // If this fires, statesOffsets is out of sync with packed.x.size.
        if (visited != totalPoints || totalPoints != packed.x.size / 3) {
            std::cout << "[SH computeGrid] coverage mismatch: visited="
                      << visited
                      << " statesOffsets[numMeshes]=" << totalPoints
                      << " packed.x.size/3=" << (packed.x.size / 3)
                      << "\n";
        }

        float cellSize = 2.0f * (float)maxRadius[0] * cellSizeFactor + (float)margin;
        // Degenerate scene (single point) or zero radius: fall back to margin.
        if (cellSize <= 0.f) cellSize = std::max((float)margin, 1e-6f);
        // One-shot warning when the user goes finer than Pabst — sh_assignCells
        // only emits 8 cells/face, so larger BVs will miss overlapped cells.
        static bool warnedFineGrid = false;
        if (cellSizeFactor < 1.0f && !warnedFineGrid) {
            std::cout << "[SH computeGrid] cellSizeFactor=" << cellSizeFactor
                      << " < 1.0 — BVs larger than cellSize/2 along an axis"
                         " will overflow the 8-slot assignment budget and"
                         " miss overlapped cells. Use as a diagnostic only.\n";
            warnedFineGrid = true;
        }

        params.numFaces    = (uint32_t)numFaces;
        params.cellSize    = cellSize;
        params.epsilon     = (float)margin;
        params.originMin[0] = mn.x;
        params.originMin[1] = mn.y;
        params.originMin[2] = mn.z;
        for (int k = 0; k < 3; ++k) {
            float extent = mx[k] - mn[k];
            uint32_t r = (uint32_t)std::ceil(extent / cellSize);
            if (r == 0) r = 1;
            params.gridRes[k] = r;
        }
        // Keep extent/numPoints/maxRadius for the per-substep log so the user
        // can correlate "grid is small" with "extent is small" or
        // "maxRadius (-> cellSize) is huge".
        lastStats.extent[0]   = mx.x - mn.x;
        lastStats.extent[1]   = mx.y - mn.y;
        lastStats.extent[2]   = mx.z - mn.z;
        lastStats.aabbMin[0]  = mn.x;
        lastStats.aabbMin[1]  = mn.y;
        lastStats.aabbMin[2]  = mn.z;
        lastStats.maxRadius   = (float)maxRadius[0];
        lastStats.numPoints   = totalPoints;
    }

    // Step 4 dispatch. Assumes computeGrid() filled `params` and the GPU has
    // already produced centroid[] and radius[].
    void runAssignCells() {
        if (numFaces == 0 || !assignCellsPSO) return;
        MetalGlobalContext::setBuffer(centroid, 0);
        MetalGlobalContext::setBuffer(radius,   1);
        MetalGlobalContext::setBytes(params,    2);
        MetalGlobalContext::setBuffer(entries,  3);
        MetalGlobalContext::setBuffer(faceCB,   4);
        MetalGlobalContext::dispatchThreads(assignCellsPSO, numFaces);
    }

    // ----- Step 5: radix sort entries by cellID -----
    //
    // Uses the 4-pass 8-bit radix sorter that already exists for the BVH's
    // morton codes. After 4 passes the sorted data is back in `entries`.
    // Sentinels (cellID=0xFFFFFFFF) sort to the tail.
    void runRadixSort() {
        if (numFaces == 0) return;
        sorter.sort(entries);
    }

    // Sentinel boundary via binary search. After Step 5 + commitAndWait the
    // unified-memory `entries.ptr` is coherent on the host.
    Index findNumValid() {
        Index n = entries.size;
        if (n == 0) return 0;
        if (entries[n - 1].cellID != 0xFFFFFFFFu) return n;
        if (entries[0].cellID == 0xFFFFFFFFu)     return 0;
        Index lo = 0, hi = n;
        while (lo < hi) {
            Index mid = lo + (hi - lo) / 2;
            if (entries[mid].cellID == 0xFFFFFFFFu) hi = mid;
            else                                    lo = mid + 1;
        }
        return lo;
    }

    // ----- Step 6: cell ranges + nH/nP per cell -----
    //
    // Three-stage: GPU markStarts -> host inclusive prefix-sum -> GPU
    // fillCellProp. The host scan is the bottleneck (~m*8 sequential adds);
    // it can be moved to a Blelloch scan kernel later but is fine on M3 for
    // v1 because we already commitAndWait between Step 5 and Step 7.

    void runMarkStarts() {
        if (numValidEntries == 0 || !markStartsPSO) return;
        uint32_t nv = (uint32_t)numValidEntries;
        MetalGlobalContext::setBuffer(entries,       0);
        MetalGlobalContext::setBytes(nv,             1);
        MetalGlobalContext::setBuffer(cellStartFlag, 2);
        MetalGlobalContext::dispatchThreads(markStartsPSO, numValidEntries);
    }

    // Inclusive prefix sum minus 1: `cellStartScan[i] = (sum flag[0..=i]) - 1`,
    // i.e. the cellIdx that entry `i` belongs to. Final running total is
    // numCells. Host-side; caller must commitAndWait first.
    void hostScanCellStarts() {
        numCells = 0;
        if (numValidEntries == 0) return;
        uint32_t running = 0;
        for (Index i = 0; i < numValidEntries; ++i) {
            running += cellStartFlag[i];
            cellStartScan[i] = running - 1;
        }
        numCells = running;
    }

    void runFillCellProp() {
        if (numCells == 0 || !fillCellPropPSO) return;
        // (Re-)allocate cellProp sized to numCells, zero-initialised.
        if (cellProp.size < numCells) {
            cellProp = VectorBase<METAL, CellPropHost>(numCells);
        }
        std::memset(cellProp.ptr, 0, sizeof(CellPropHost) * numCells);

        uint32_t nv = (uint32_t)numValidEntries;
        MetalGlobalContext::setBuffer(entries,       0);
        MetalGlobalContext::setBuffer(cellStartFlag, 1);
        MetalGlobalContext::setBuffer(cellStartScan, 2);
        MetalGlobalContext::setBytes(nv,             3);
        MetalGlobalContext::setBytes(params,         4);
        MetalGlobalContext::setBuffer(cellProp,      5);
        MetalGlobalContext::dispatchThreads(fillCellPropPSO, numValidEntries);
    }

    void validateCellProp(Index N = 8) {
        if (numCells == 0) {
            std::cout << "[SH Step6] no active cells\n";
            return;
        }
        uint64_t sumH = 0, sumP = 0;
        Index    badStart = numCells; // sentinel meaning "none"
        for (Index i = 0; i < numCells; ++i) {
            sumH += cellProp[i].nH;
            sumP += cellProp[i].nP;
            if (i > 0 && cellProp[i].start <= cellProp[i - 1].start
                && badStart == numCells) {
                badStart = i;
            }
        }
        bool sumOk     = (sumH + sumP == (uint64_t)numValidEntries);
        bool startOk   = (badStart == numCells);
        std::cout << "[SH Step6] cells=" << numCells
                  << " sum(nH)=" << sumH
                  << " sum(nP)=" << sumP
                  << " total=" << (sumH + sumP)
                  << "/" << numValidEntries
                  << (sumOk ? " match" : " MISMATCH")
                  << " starts=" << (startOk ? "increasing" : "BROKEN")
                  << "\n";
        if (!startOk) {
            std::cout << "  first non-increasing start at i=" << badStart
                      << " start[" << (badStart - 1) << "]="
                      << cellProp[badStart - 1].start
                      << " start[" << badStart << "]="
                      << cellProp[badStart].start << "\n";
        }
        Index n = std::min<Index>(N, numCells);
        for (Index i = 0; i < n; ++i) {
            const auto& cp = cellProp[i];
            std::cout << "  cell " << i
                      << " start=" << cp.start
                      << " nH=" << cp.nH
                      << " nP=" << cp.nP
                      << " type=" << cp.cellType
                      << " (cellID=" << entries[cp.start].cellID << ")"
                      << "\n";
        }
    }

    // ----- Step 7: per-cell pairCnt + exclusive prefix -> P -----
    //
    // pairCnt = nH*(nH-1)/2 + nH*nP. Phantom-only cells (nH==0) produce 0
    // pairs and are silently dropped (no fictitious-phantom promotion in
    // v1).  pairPrefix[C+1] is exclusive-scan of pairCnt; the last element
    // is the total candidate-pair count P consumed by Step 8.

    void runComputePairCount() {
        if (numCells == 0 || !computePairCountPSO) return;
        uint32_t nc = (uint32_t)numCells;
        MetalGlobalContext::setBuffer(cellProp, 0);
        MetalGlobalContext::setBytes(nc,        1);
        MetalGlobalContext::dispatchThreads(computePairCountPSO, numCells);
    }

    void hostScanPairPrefix() {
        numCandidatePairs = 0;
        if (numCells == 0) return;
        if (pairPrefix.size < numCells + 1) {
            pairPrefix = VectorBase<METAL, uint32_t>(numCells + 1);
        }
        uint64_t running = 0;
        for (Index i = 0; i < numCells; ++i) {
            pairPrefix[i] = (uint32_t)running;
            running += cellProp[i].pairCnt;
        }
        pairPrefix[numCells] = (uint32_t)running;
        numCandidatePairs = (Index)running;
    }

    void validatePairPrefix(Index N = 8) {
        // Independent recompute of pairCnt from nH/nP, summed.
        uint64_t cpuTotal = 0;
        Index    badCnt   = numCells;
        Index    nonzeroCells = 0;
        for (Index i = 0; i < numCells; ++i) {
            uint32_t h = cellProp[i].nH;
            uint32_t p = cellProp[i].nP;
            uint32_t expected = (h * (h - 1u)) / 2u + h * p;
            if (cellProp[i].pairCnt != expected && badCnt == numCells) {
                badCnt = i;
            }
            cpuTotal += expected;
            if (expected > 0) ++nonzeroCells;
        }
        bool totalOk = (cpuTotal == (uint64_t)numCandidatePairs);
        std::cout << "[SH Step7] P=" << numCandidatePairs
                  << " (cpu sum=" << cpuTotal
                  << (totalOk ? " match" : " MISMATCH") << ")"
                  << " active=" << nonzeroCells << "/" << numCells
                  << " pairCnt=" << ((badCnt == numCells) ? "ok" : "BAD")
                  << "\n";
        if (badCnt != numCells) {
            uint32_t h = cellProp[badCnt].nH;
            uint32_t p = cellProp[badCnt].nP;
            std::cout << "  first bad pairCnt at cell " << badCnt
                      << " nH=" << h << " nP=" << p
                      << " expected=" << ((h*(h-1u))/2u + h*p)
                      << " got=" << cellProp[badCnt].pairCnt << "\n";
        }
        Index n = std::min<Index>(N, numCells);
        for (Index i = 0; i < n; ++i) {
            std::cout << "  cell " << i
                      << " nH=" << cellProp[i].nH
                      << " nP=" << cellProp[i].nP
                      << " pairCnt=" << cellProp[i].pairCnt
                      << " pairPrefix=" << pairPrefix[i] << "\n";
        }
        std::cout << "  pairPrefix[" << numCells << "]=" << pairPrefix[numCells]
                  << "\n";
    }

    // ----- Step 8: per-pair broad-phase emit -----
    //
    // Dispatches P threads, one per candidate pair. Output is the same
    // BroadCollision buffer the BVH path writes to (Scene::packedCollisionData),
    // so the existing narrow_pt_tri kernel consumes SH output unchanged.

    struct SHBroadParamsHost {
        uint32_t numCandidatePairs;
        uint32_t numCells;
        uint32_t maxNumCollisions;
        uint32_t enableSelfCollisions;
        float    epsilon;
    };
    static_assert(sizeof(SHBroadParamsHost) == 20,
                  "SHBroadParamsHost must match metal SHBroadParams (20 bytes)");

    void runBroadPhase(PR margin, bool enableSelfCollisions) {
        if (numCandidatePairs == 0 || !broadPhasePSO) return;
        auto& packed    = Scene<METAL, PR>::packedMeshData;
        auto& packedCol = Scene<METAL, PR>::packedCollisionData;

        SHBroadParamsHost bp{};
        bp.numCandidatePairs    = (uint32_t)numCandidatePairs;
        bp.numCells             = (uint32_t)numCells;
        bp.maxNumCollisions     = (uint32_t)packedCol.maxNumCollisions;
        bp.enableSelfCollisions = enableSelfCollisions ? 1u : 0u;
        bp.epsilon              = (float)margin;

        MetalGlobalContext::setBuffer(entries,                   0);
        MetalGlobalContext::setBuffer(cellProp,                  1);
        MetalGlobalContext::setBuffer(pairPrefix,                2);
        MetalGlobalContext::setBuffer(faceCB,                    3);
        MetalGlobalContext::setBuffer(faceObj,                   4);
        MetalGlobalContext::setBuffer(packed.facets,             5);
        MetalGlobalContext::setBuffer(packed.facetsOffsets,      6);
        MetalGlobalContext::setBuffer(centroid,                  7);
        MetalGlobalContext::setBuffer(radius,                    8);
        MetalGlobalContext::setBuffer(meshBehaviors,             9);
        MetalGlobalContext::setBuffer(meshShapes,               10);
        MetalGlobalContext::setBytes(bp,                        11);
        MetalGlobalContext::setBuffer(packedCol.numBroadCollisions, 12);
        MetalGlobalContext::setBuffer(packedCol.broadCollisions,    13);
        MetalGlobalContext::dispatchThreads(broadPhasePSO, numCandidatePairs);
    }

    void validateBroadPhase() {
        auto& packedCol = Scene<METAL, PR>::packedCollisionData;
        uint32_t numOut = (uint32_t)packedCol.numBroadCollisions[0];
        bool overflow   = numOut > (uint32_t)packedCol.maxNumCollisions;
        std::cout << "[SH Step8] candidatePairs=" << numCandidatePairs
                  << " broadCollisions=" << numOut
                  << "/" << packedCol.maxNumCollisions
                  << (overflow ? " OVERFLOW" : "")
                  << "\n";
    }

    void validateRadixSort() {
        if (numFaces == 0) return;
        numValidEntries = findNumValid();

        // Cross-check vs Step 4's per-element count.
        Index step4Valid = 0;
        for (Index i = 0; i < entries.size; ++i)
            if (entries[i].cellID != 0xFFFFFFFFu) ++step4Valid;

        // Sortedness on the valid prefix.
        Index firstViolation = numValidEntries; // sentinel value
        for (Index i = 1; i < numValidEntries; ++i) {
            if (entries[i - 1].cellID > entries[i].cellID) {
                firstViolation = i;
                break;
            }
        }
        std::cout << "[SH Step5] numValid=" << numValidEntries
                  << "/" << entries.size
                  << " (step4 count=" << step4Valid
                  << ((step4Valid == numValidEntries) ? " match" : " MISMATCH")
                  << ") sorted="
                  << ((firstViolation == numValidEntries) ? "yes" : "NO")
                  << "\n";
        if (firstViolation != numValidEntries) {
            std::cout << "  first violation at i=" << firstViolation
                      << " cellID[" << (firstViolation - 1) << "]="
                      << entries[firstViolation - 1].cellID
                      << " > cellID[" << firstViolation << "]="
                      << entries[firstViolation].cellID << "\n";
        }
    }

    // Spot-check: per-face entry counts, CB popcount = entry count, and
    // the home cell hash recomputed on the CPU.
    void validateAssignCells(Index N = 5) {
        if (numFaces == 0) return;
        Index totalValid = 0;
        Index minSlots = 8, maxSlots = 0;
        for (Index i = 0; i < numFaces; ++i) {
            Index v = 0;
            for (uint k = 0; k < 8; ++k)
                if (entries[i * 8 + k].cellID != 0xFFFFFFFFu) ++v;
            totalValid += v;
            minSlots = std::min<Index>(minSlots, v);
            maxSlots = std::max<Index>(maxSlots, v);
        }
        std::cout << "[SH Step4] entries: " << totalValid
                  << " valid / " << (numFaces * 8) << " total ("
                  << (100.0 * totalValid / (numFaces * 8)) << "%)"
                  << " per-face min=" << minSlots
                  << " max=" << maxSlots << "\n";

        Index n = std::min<Index>(N, numFaces);
        for (Index i = 0; i < n; ++i) {
            tinym::vec3_view cView(centroid.ptr + i * 3);
            tinym::vec3 c(cView[0], cView[1], cView[2]);
            uint32_t gx = (uint32_t)std::floor((c.x - params.originMin[0]) / params.cellSize);
            uint32_t gy = (uint32_t)std::floor((c.y - params.originMin[1]) / params.cellSize);
            uint32_t gz = (uint32_t)std::floor((c.z - params.originMin[2]) / params.cellSize);
            gx = std::min(gx, params.gridRes[0] - 1);
            gy = std::min(gy, params.gridRes[1] - 1);
            gz = std::min(gz, params.gridRes[2] - 1);
            uint32_t cpuHomeHash = gz * params.gridRes[1] * params.gridRes[0]
                                 + gy * params.gridRes[0]
                                 + gx;
            uint32_t cpuHomeT = (gx & 1u) | ((gy & 1u) << 1) | ((gz & 1u) << 2);

            uint32_t gpuHomeHash = entries[i * 8].cellID;
            uint32_t gpuValue    = entries[i * 8].value;
            uint32_t gpuHomeT    = gpuValue & 0x7u;
            uint32_t gpuPhantom  = (gpuValue >> 3) & 0x1u;
            uint32_t gpuFaceId   = gpuValue >> 4;

            int valid = 0;
            for (uint k = 0; k < 8; ++k)
                if (entries[i * 8 + k].cellID != 0xFFFFFFFFu) ++valid;

            uint8_t cb = faceCB[i];
            int popcount = __builtin_popcount((unsigned)cb);

            std::cout << "  face " << i
                      << " home cpu/gpu hash=" << cpuHomeHash << "/" << gpuHomeHash
                      << " homeT cpu/gpu=" << cpuHomeT << "/" << gpuHomeT
                      << " phantom=" << gpuPhantom
                      << " faceId=" << gpuFaceId
                      << " entries=" << valid
                      << " CB=0x" << std::hex << (int)cb << std::dec
                      << " popcount=" << popcount
                      << ((popcount == valid) ? " [ok]" : " [MISMATCH]")
                      << "\n";
        }
    }

    void validateGrid() {
        std::cout << "[SH Step3] origin=("
                  << params.originMin[0] << ","
                  << params.originMin[1] << ","
                  << params.originMin[2] << ")"
                  << " cellSize=" << params.cellSize
                  << " gridRes=("
                  << params.gridRes[0] << ","
                  << params.gridRes[1] << ","
                  << params.gridRes[2] << ")"
                  << " totalCells=" << ((uint64_t)params.gridRes[0]
                                       * params.gridRes[1]
                                       * params.gridRes[2])
                  << "\n";
    }

    // Compare GPU `maxRadius[0]` against CPU std::max over the same array.
    void validateMaxRadius() {
        if (numFaces == 0) return;
        float gpuMax = (float)maxRadius[0];
        float cpuMax = 0.0f;
        for (Index i = 0; i < numFaces; ++i)
            cpuMax = std::max(cpuMax, (float)radius[i]);
        std::cout << "[SH Step2] maxRadius cpu=" << cpuMax
                  << " gpu=" << gpuMax
                  << " |diff|=" << std::abs(cpuMax - gpuMax) << "\n";
    }

    // One-shot sanity check: GPU result vs CPU recompute on the first N
    // faces. Called manually from Simulator::initialize() while Step 1 is
    // being verified; remove the call once trust is established.
    void validateBuildBV(Index N = 5) {
        if (numFaces == 0) return;
        auto& packed = Scene<METAL, PR>::packedMeshData;
        Index n = std::min<Index>(N, numFaces);
        std::cout << "[SH Step1] verifying BV for first " << n
                  << " of " << numFaces << " faces:\n";
        float maxRelErr = 0.0f;
        for (Index i = 0; i < n; ++i) {
            uint32_t obj   = (uint32_t)faceObj[i];
            uint32_t vbase = (uint32_t)packed.statesOffsets[obj];
            uint32_t f0 = (uint32_t)packed.facets[i * 3 + 0];
            uint32_t f1 = (uint32_t)packed.facets[i * 3 + 1];
            uint32_t f2 = (uint32_t)packed.facets[i * 3 + 2];
            tinym::vec3_view v0(packed.x.ptr + (f0 + vbase) * 3);
            tinym::vec3_view v1(packed.x.ptr + (f1 + vbase) * 3);
            tinym::vec3_view v2(packed.x.ptr + (f2 + vbase) * 3);
            tinym::vec3 c = (v0 + v1 + v2) * (1.0f / 3.0f);
            float d0 = (c - v0).norm();
            float d1 = (c - v1).norm();
            float d2 = (c - v2).norm();
            float rCpu = std::max({d0, d1, d2});

            tinym::vec3_view gC(centroid.ptr + i * 3);
            float rGpu = radius[i];

            float dC = (c - gC).norm();
            float dR = std::abs(rCpu - rGpu);
            float rel = (rCpu > 1e-6f) ? (dR / rCpu) : dR;
            maxRelErr = std::max(maxRelErr, rel);
            std::cout << "  face " << i << " obj=" << obj
                      << " cpuC=(" << c.x << "," << c.y << "," << c.z << ")"
                      << " gpuC=(" << gC[0] << "," << gC[1] << "," << gC[2] << ")"
                      << " cpuR=" << rCpu << " gpuR=" << rGpu
                      << " |dC|=" << dC << " |dR|=" << dR << "\n";
        }
        std::cout << "[SH Step1] max relative radius error: "
                  << maxRelErr << "\n";
    }

    void refit() {
        // The grid is rebuilt every frame inside detectCollisions(); refit()
        // is intentionally a no-op so the call site mirrors the BVH path.
    }

    void enlargeTrajectory(PR /*dt*/) {
        // CCD swept BVs are out of scope for v1.
    }

    void queryBegin() {
        Scene<METAL, PR>::packedCollisionData.numBroadCollisions[0] = 0;
    }

    void detectCollisions(PR margin, bool enableSelfCollisions = true) {
        // Each stage is wall-time-measured once, and that single number feeds
        // both `lastStats` (for stdout per-substep logging) and the
        // FrameProfiler (for the GUI timing window). Avoids two redundant
        // clock reads per stage.
        using Clock = std::chrono::steady_clock;
        auto run = [&](const char* name, auto&& fn, double& dst) {
            auto a = Clock::now();
            fn();
            auto b = Clock::now();
            dst = std::chrono::duration<double, std::milli>(b - a).count();
            if (profiler) profiler->addSample(std::string(name), dst);
        };

        auto t0 = Clock::now();
        queryBegin();

        run("sh_buildBV",    [&]{ runBuildBV(); },                           lastStats.ms_buildBV);
        run("sh_reduce",     [&]{
            runReduceMaxRadius();
            // Step 3 reads maxRadius[0] and packedMeshData.x on the host, so
            // we must wait for the kernels above to finish writing.
            MetalGlobalContext::commitAndWait();
        }, lastStats.ms_reduce);
        run("sh_grid",       [&]{ computeGrid(margin); },                    lastStats.ms_grid);
        run("sh_assign",     [&]{ runAssignCells(); },                       lastStats.ms_assign);
        run("sh_sort",       [&]{
            runRadixSort();
            // Step 6 needs numValidEntries on host, which requires commit + scan.
            MetalGlobalContext::commitAndWait();
            numValidEntries = findNumValid();
        }, lastStats.ms_sort);
        run("sh_cellprop",   [&]{
            runMarkStarts();
            MetalGlobalContext::commitAndWait();
            hostScanCellStarts();
            runFillCellProp();
        }, lastStats.ms_cellprop);
        run("sh_pairprefix", [&]{
            runComputePairCount();
            // Step 7's host scan needs cellProp[].pairCnt visible.
            MetalGlobalContext::commitAndWait();
            hostScanPairPrefix();
        }, lastStats.ms_pairprefix);
        run("sh_broad",      [&]{
            runBroadPhase(margin, enableSelfCollisions);
            // Force a commit when verbose so the host-side ms_broad reflects
            // actual GPU work and numBroadOut is observable. Steady-state mode
            // skips this so the broad-phase output stays pipelined into the
            // narrow phase via the same command buffer.
            if (verbose) MetalGlobalContext::commitAndWait();
        }, lastStats.ms_broad);

        auto t1 = Clock::now();
        lastStats.ms_total = std::chrono::duration<double, std::milli>(t1 - t0).count();
        lastStats.numFaces          = numFaces;
        lastStats.numValidEntries   = numValidEntries;
        lastStats.numCells          = numCells;
        lastStats.numCandidatePairs = numCandidatePairs;
        lastStats.cellSize          = params.cellSize;
        lastStats.gridRes[0]        = params.gridRes[0];
        lastStats.gridRes[1]        = params.gridRes[1];
        lastStats.gridRes[2]        = params.gridRes[2];

        if (verbose) {
            // Scan cellProp host-side for the heavy-cell signal — only when
            // verbose so we don't pay the O(numCells) sweep every substep.
            Index maxH = 0, maxP = 0, maxC = 0;
            for (Index i = 0; i < numCells; ++i) {
                const auto& cp = cellProp[i];
                if ((Index)cp.nH      > maxH) maxH = cp.nH;
                if ((Index)cp.nP      > maxP) maxP = cp.nP;
                if ((Index)cp.pairCnt > maxC) maxC = cp.pairCnt;
            }
            lastStats.maxNH      = maxH;
            lastStats.maxNP      = maxP;
            lastStats.maxPairCnt = maxC;
            lastStats.numBroadOut =
                Scene<METAL, PR>::packedCollisionData.numBroadCollisions[0];
        }
    }

    // One compact line per call. Caller picks frame/substep labels.
    void printLastStats(std::ostream& os, Index frame, Index substep) const {
        os << "[F=" << frame << " S=" << substep << "] sh:"
           << " faces=" << lastStats.numFaces
           << " valid=" << lastStats.numValidEntries
           << " cells=" << lastStats.numCells
           << " pairs=" << lastStats.numCandidatePairs
           << " broadOut=" << lastStats.numBroadOut
           << " maxNH=" << lastStats.maxNH
           << " maxNP=" << lastStats.maxNP
           << " maxPairCnt=" << lastStats.maxPairCnt
           << " pts=" << lastStats.numPoints
           << " ext=" << lastStats.extent[0]
           << "x" << lastStats.extent[1]
           << "x" << lastStats.extent[2]
           << " maxR=" << lastStats.maxRadius
           << " csF=" << cellSizeFactor
           << " cellSize=" << lastStats.cellSize
           << " grid=" << lastStats.gridRes[0]
           << "x" << lastStats.gridRes[1]
           << "x" << lastStats.gridRes[2]
           << " | bv=" << lastStats.ms_buildBV
           << " red=" << lastStats.ms_reduce
           << " grid=" << lastStats.ms_grid
           << " asgn=" << lastStats.ms_assign
           << " srt=" << lastStats.ms_sort
           << " cell=" << lastStats.ms_cellprop
           << " pp=" << lastStats.ms_pairprefix
           << " brd=" << lastStats.ms_broad
           << " tot=" << lastStats.ms_total << "ms\n";
    }

    void queryEnd() {
        MetalGlobalContext::commitAndWait();
        auto& packedCol = Scene<METAL, PR>::packedCollisionData;
        if (packedCol.numBroadCollisions[0] > packedCol.maxNumCollisions) {
            std::cout << "[SH] broad-phase overflow: "
                      << packedCol.numBroadCollisions[0]
                      << "/" << packedCol.maxNumCollisions << "\n";
        }
    }

    void showBox()      { /* debug-only; defer */ }
    void showSceneBox() { /* debug-only; defer */ }

    void queryClickRay(const Ray& /*ray*/) {
        // Click ray-pick continues to use BVH; SpatialHashing is broadphase-only.
    }
};


// ============================================================================
// Multi-level (hierarchical hash-grid / hgrid) spatial-hashing broad phase.
//
// ADDITIVE alongside SpatialHashing<METAL,PR> (single-level) — both share the
// BroadCollision output convention and the BVH<SCENE,OBJECT> surface, so the
// Simulator can flip the active broad phase at runtime. Algorithm + kernels:
// src/metal/mlspatialhashing.metal (ml_buildBV / ml_assignCells /
// ml_broadPhase) reusing the single-level radix sort and sh_reduceMaxRadius.
//
//   * L geometric grid levels: cellSize[k] = c0*2^k, cellSize[L-1] = 2*maxR.
//   * each face -> ONE home cell at its fitting level Lf (finest cell that fits
//     its inflated BV). No phantom replication. Key = (level<<28)|linearCellId,
//     value = global face id; entries (one per face) radix-sorted by key.
//   * the per-face broad phase walks levels Lf..L-1, binary-searching the sorted
//     entries for each overlapped cell and colliding against the faces HOME
//     there. Dedup: own level emits faceB>faceA; coarser levels are owned by the
//     (strictly finer) querying face. Cells stay sparse -> bounded pair work,
//     instead of the O(N^3) packed-coarse-cell blowup phantom replication caused.
//   * oversized primitives (the floor) are EXCLUDED via a per-mesh
//     AABB-diagonal threshold: excluded faces get radius 0 and emit no entries,
//     so they leave neither the max-radius reduction nor the scene AABB,
//     keeping cell size and per-cell occupancy bounded (the goal's
//     "바닥 오브젝트는 너무 큰 primitive로 테스트에서 제외").
template <typename BE, typename PR>
struct MultiLevelSpatialHashing {};

template<typename PR>
struct MultiLevelSpatialHashing<METAL, PR> {
    static constexpr uint32_t ML_MAX_LEVELS = 4;

    // Host mirror of metal MLParams. Plain 4-byte scalars/arrays only — no
    // packed_* — so the layout is padding-free and byte-matches the kernel.
    struct MLParamsHost {
        uint32_t numFaces;
        uint32_t numLevels;
        float    epsilon;
        float    cellSize[ML_MAX_LEVELS];     // 4 floats
        uint32_t gridRes[ML_MAX_LEVELS * 3];  // 12 uints, [level*3 + axis]
        float    originMin[3];
    };
    static_assert(sizeof(MLParamsHost) == 88,
                  "MLParamsHost must match metal MLParams layout (88 bytes)");

    struct MLBroadParamsHost {
        uint32_t numFaces;
        uint32_t numValid;
        uint32_t maxNumCollisions;
        uint32_t enableSelfCollisions;
        uint32_t numLevels;
        float    epsilon;
    };
    static_assert(sizeof(MLBroadParamsHost) == 24,
                  "MLBroadParamsHost must match metal MLBroadParams (24 bytes)");

    struct SHEntry { uint32_t cellID; uint32_t value; };
    static_assert(sizeof(SHEntry) == 8, "SHEntry must be 8 bytes");

    // ----- Buffers -----
    // Home-only insertion: one entry per face (its home cell), so `entries` is
    // numFaces — no phantom replication, no per-cell property / pair-prefix
    // arrays. The per-face broad phase walks levels and binary-searches this
    // sorted buffer directly.
    VectorBase<METAL, PR>          centroid;             // 3*m
    VectorBase<METAL, PR>          radius;               // m
    VectorBase<METAL, PR>          maxRadius;            // 1
    VectorBase<METAL, PR>          radiusReducePartial;  // ceil(m/256)
    VectorBase<METAL, PR>          radiusReducePartial2;
    VectorBase<METAL, Index>       faceObj;              // m
    VectorBase<METAL, uint8_t>     faceExclude;          // m, 1 == drop from grid
    VectorBase<METAL, uint32_t>    meshBehaviors;        // numMeshes
    VectorBase<METAL, uint32_t>    meshShapes;           // numMeshes
    VectorBase<METAL, SHEntry>     entries;              // m, cellID-sorted, sentinel tail

    MTL::ComputePipelineState* buildBVPSO          = nullptr;
    MTL::ComputePipelineState* reduceMaxRadiusPSO  = nullptr;
    MTL::ComputePipelineState* assignCellsPSO      = nullptr;
    MTL::ComputePipelineState* broadPhasePSO       = nullptr;

    Scene<METAL, PR>* scenePtr = nullptr;
    Index numFaces = 0;
    Index numValidEntries = 0;
    Index numCells = 0;
    Index numCandidatePairs = 0;
    Index numExcludedFaces = 0;

    RadixSorter<METAL, SHEntry> sorter;
    MLParamsHost params{};
    profiler::FrameProfiler* profiler = nullptr;

    // Tunables.
    int   numLevels       = 4;      // MAX levels (cap); active count auto-derived
                                    // per frame from the min/max face-size ratio.
    float cellSizeFactor  = 1.0f;   // multiplier on the finest (min-radius) cell.
    float floorExcludeDiag = 8.0f;  // mesh AABB-diagonal above this -> excluded.
    bool  verbose = false;

    struct LastRunStats {
        Index  numFaces = 0, numValidEntries = 0, numCells = 0,
               numCandidatePairs = 0, numBroadOut = 0, numExcluded = 0;
        Index  numPoints = 0;
        int    numLevels = 0;
        float  maxRadius = 0.f, cellSizeTop = 0.f;
        float  extent[3] = {0,0,0};
        double ms_buildBV=0, ms_reduce=0, ms_grid=0, ms_assign=0,
               ms_sort=0, ms_cellprop=0, ms_pairprefix=0, ms_broad=0, ms_total=0;
    };
    LastRunStats lastStats{};

    MultiLevelSpatialHashing() = default;

    int effectiveLevels() const {
        int L = numLevels;
        if (L < 1) L = 1;
        if (L > (int)ML_MAX_LEVELS) L = (int)ML_MAX_LEVELS;
        return L;
    }

    void memoryAllocation() {
        if (numFaces == 0) return;
        // Home-only insertion: exactly one entry per face (its home cell). No
        // phantom replication, so the entries buffer is numFaces — not the old
        // numFaces*MAXL*8 — which is what kept the radix sort and pair work
        // bounded. The cross-level query walk reads this same sorted buffer.
        if (centroid.ptr && centroid.size == numFaces * 3
            && entries.size == numFaces) return;
        centroid = VectorBase<METAL, PR>(numFaces * 3);
        radius   = VectorBase<METAL, PR>(numFaces);

        constexpr Index TG = 256;
        Index ng1 = (numFaces + TG - 1) / TG;
        Index ng2 = std::max<Index>((ng1 + TG - 1) / TG, 1);
        radiusReducePartial  = VectorBase<METAL, PR>(std::max<Index>(ng1, 1));
        radiusReducePartial2 = VectorBase<METAL, PR>(ng2);
        if (!maxRadius.ptr) maxRadius = VectorBase<METAL, PR>(1);

        entries = VectorBase<METAL, SHEntry>(numFaces);
    }

    void rebuildFaceObj() {
        if (!scenePtr) return;
        auto& packed = Scene<METAL, PR>::packedMeshData;
        Index m = packed.facets.size / 3;
        if (faceObj.ptr && faceObj.size == m) return;
        faceObj = VectorBase<METAL, Index>(m);
        Index numMeshes = Scene<METAL, PR>::numMeshes;
        for (Index obj = 0; obj < numMeshes; ++obj) {
            Index begin = packed.facetsOffsets[obj];
            Index end   = packed.facetsOffsets[obj + 1];
            for (Index f = begin; f < end; ++f) faceObj[f] = obj;
        }
    }

    void rebuildMeshKinds() {
        Index numMeshes = Scene<METAL, PR>::numMeshes;
        if (meshBehaviors.ptr && meshBehaviors.size == numMeshes) return;
        meshBehaviors = VectorBase<METAL, uint32_t>(numMeshes);
        meshShapes    = VectorBase<METAL, uint32_t>(numMeshes);
        auto& meshes = Scene<METAL, PR>::meshes;
        for (Index i = 0; i < numMeshes; ++i) {
            meshBehaviors[i] = (uint32_t)meshes[i].behaviorType;
            meshShapes[i]    = (uint32_t)meshes[i].shapeType;
        }
    }

    // Per-mesh AABB-diagonal exclusion. Oversized meshes (the floor) are
    // dropped from the grid. Rebuilt every build() because positions move; the
    // exclusion is geometric (current AABB) so a mesh that shrinks/grows past
    // the threshold re-classifies automatically.
    void rebuildFaceExclude() {
        if (numFaces == 0) return;
        auto& packed = Scene<METAL, PR>::packedMeshData;
        Index numMeshes = Scene<METAL, PR>::numMeshes;
        if (!faceExclude.ptr || faceExclude.size != numFaces)
            faceExclude = VectorBase<METAL, uint8_t>(numFaces);
        numExcludedFaces = 0;
        for (Index obj = 0; obj < numMeshes; ++obj) {
            Index vb = packed.statesOffsets[obj];
            Index ve = packed.statesOffsets[obj + 1];
            bool excluded = false;
            if (ve > vb) {
                tinym::vec3 mn(packed.x.ptr[vb*3+0], packed.x.ptr[vb*3+1], packed.x.ptr[vb*3+2]);
                tinym::vec3 mx = mn;
                for (Index v = vb; v < ve; ++v) {
                    tinym::vec3 p(packed.x.ptr[v*3+0], packed.x.ptr[v*3+1], packed.x.ptr[v*3+2]);
                    mn = tinym::min(mn, p);
                    mx = tinym::max(mx, p);
                }
                float diag = (mx - mn).norm();
                excluded = (diag > floorExcludeDiag);
            }
            Index fb = packed.facetsOffsets[obj];
            Index fe = packed.facetsOffsets[obj + 1];
            for (Index f = fb; f < fe; ++f) {
                faceExclude[f] = excluded ? 1u : 0u;
                if (excluded) ++numExcludedFaces;
            }
        }
    }

    void build(Scene<METAL, PR>& scene) {
        scenePtr = &scene;
        auto& packed = Scene<METAL, PR>::packedMeshData;
        numFaces = packed.facets.size / 3;
        rebuildFaceObj();
        rebuildMeshKinds();
        memoryAllocation();
        rebuildFaceExclude();
        if (!buildBVPSO)          buildBVPSO          = MetalKernelContext::getPSO("ml_buildBV");
        if (!reduceMaxRadiusPSO)  reduceMaxRadiusPSO  = MetalKernelContext::getPSO("sh_reduceMaxRadius");
        if (!assignCellsPSO)      assignCellsPSO      = MetalKernelContext::getPSO("ml_assignCells");
        if (!broadPhasePSO)       broadPhasePSO       = MetalKernelContext::getPSO("ml_broadPhase");
    }

    void runBuildBV() {
        if (numFaces == 0 || !buildBVPSO) return;
        auto& packed = Scene<METAL, PR>::packedMeshData;
        params.numFaces  = (uint32_t)numFaces;
        params.numLevels = (uint32_t)effectiveLevels();
        MetalGlobalContext::setBuffer(packed.x, 0);
        MetalGlobalContext::setBuffer(packed.statesOffsets, 1);
        MetalGlobalContext::setBuffer(packed.facets, 2);
        MetalGlobalContext::setBuffer(faceObj, 3);
        MetalGlobalContext::setBuffer(faceExclude, 4);
        MetalGlobalContext::setBytes(params, 5);
        MetalGlobalContext::setBuffer(centroid, 6);
        MetalGlobalContext::setBuffer(radius, 7);
        MetalGlobalContext::dispatchThreads(buildBVPSO, numFaces);
    }

    void runReduceMaxRadius() {
        if (numFaces == 0 || !reduceMaxRadiusPSO) return;
        constexpr Index TG = 256;
        auto dispatch = [&](VectorBase<METAL, PR>& in, VectorBase<METAL, PR>& out, uint32_t cnt) {
            Index ng = (cnt + TG - 1) / TG;
            MetalGlobalContext::setBuffer(in, 0);
            MetalGlobalContext::setBuffer(out, 1);
            MetalGlobalContext::setBytes(cnt, 2);
            MetalGlobalContext::dispatchThreads(reduceMaxRadiusPSO, ng * TG, TG);
            return ng;
        };
        uint32_t cnt = (uint32_t)numFaces;
        Index ng = (cnt + TG - 1) / TG;
        VectorBase<METAL, PR>* dst = (ng == 1) ? &maxRadius : &radiusReducePartial;
        dispatch(radius, *dst, cnt);
        VectorBase<METAL, PR>* src = dst;
        VectorBase<METAL, PR>* alt = (src == &radiusReducePartial)
                                     ? &radiusReducePartial2 : &radiusReducePartial;
        while (ng > 1) {
            cnt = (uint32_t)ng;
            Index ng2 = (cnt + TG - 1) / TG;
            VectorBase<METAL, PR>* nextDst = (ng2 == 1) ? &maxRadius : alt;
            dispatch(*src, *nextDst, cnt);
            ng = ng2;
            src = nextDst;
            alt = (alt == &radiusReducePartial) ? &radiusReducePartial2 : &radiusReducePartial;
        }
    }

    // Host: scene AABB over NON-excluded meshes, then geometric per-level cell
    // sizes / grid resolutions from maxRadius. Caller must commitAndWait first.
    void computeGrid(PR margin) {
        if (numFaces == 0) return;
        auto& packed = Scene<METAL, PR>::packedMeshData;
        Index numMeshes = Scene<METAL, PR>::numMeshes;
        params.numFaces  = (uint32_t)numFaces;
        params.epsilon   = (float)margin;

        // AABB over included meshes only (so the 50-wide floor doesn't blow up
        // grid resolution even if some excluded face slipped through).
        bool have = false;
        tinym::vec3 mn(0,0,0), mx(0,0,0);
        for (Index obj = 0; obj < numMeshes; ++obj) {
            Index vb = packed.statesOffsets[obj];
            Index ve = packed.statesOffsets[obj + 1];
            if (ve <= vb) continue;
            Index ff = packed.facetsOffsets[obj];
            if (ff < numFaces && faceExclude.ptr && faceExclude[ff]) continue;
            for (Index v = vb; v < ve; ++v) {
                tinym::vec3 p(packed.x.ptr[v*3+0], packed.x.ptr[v*3+1], packed.x.ptr[v*3+2]);
                if (!have) { mn = mx = p; have = true; }
                else { mn = tinym::min(mn, p); mx = tinym::max(mx, p); }
            }
        }
        if (!have) { mn = tinym::vec3(0,0,0); mx = tinym::vec3(0,0,0); }

        // Min face radius over INCLUDED faces (radius[]==0 for excluded). The
        // radius buffer is host-coherent here (caller commitAndWaits after the
        // reduce). Drives the FINEST cell so the smallest face maps ~1/cell.
        float maxR = (float)maxRadius[0];
        float minR = maxR;
        for (Index f = 0; f < numFaces; ++f) {
            float rf = (float)radius[f];
            if (rf > 1e-7f && rf < minR) minR = rf;
        }
        if (minR <= 0.f) minR = std::max(maxR, 1e-6f);
        // Clamp the finest cell so the dynamic range never exceeds what the
        // level budget spans (2^(MAXL-1) = 8x). Without this, a single
        // degenerate (near-zero-area) draped-cloth triangle collapses c0 -> 0,
        // which caps every level's resolution and re-creates the pile-up.
        float minFloor = maxR / (float)(1u << (ML_MAX_LEVELS - 1));
        if (minR < minFloor) minR = minFloor;

        // c0 = finest cell = 2*minR (a smallest face fits in one cell).
        float c0 = 2.0f * minR * cellSizeFactor;
        if (c0 <= 0.f) c0 = std::max((float)margin, 1e-6f);
        // Active levels: enough that cellSize[L-1] = c0*2^(L-1) covers the
        // largest margin-inflated BV (2*(maxR+margin)). Capped by the user's
        // numLevels and the hard ML_MAX_LEVELS buffer budget.
        float topNeeded = 2.0f * (maxR + (float)margin);
        int L = 1;
        while (L < effectiveLevels() && c0 * (float)(1u << (L - 1)) < topNeeded) ++L;
        params.numLevels = (uint32_t)L;

        params.originMin[0] = mn.x;
        params.originMin[1] = mn.y;
        params.originMin[2] = mn.z;
        float ext[3] = { mx.x - mn.x, mx.y - mn.y, mx.z - mn.z };
        const uint32_t RES_CAP = 640;   // 640^3 < 2^28 linear-id budget
        for (int k = 0; k < (int)ML_MAX_LEVELS; ++k) {
            float cs = c0 * (float)(1u << k);
            params.cellSize[k] = cs;
            for (int a = 0; a < 3; ++a) {
                uint32_t r = (uint32_t)std::ceil(ext[a] / cs);
                if (r == 0) r = 1;
                if (r > RES_CAP) r = RES_CAP;
                params.gridRes[k*3 + a] = r;
            }
        }

        lastStats.extent[0] = ext[0];
        lastStats.extent[1] = ext[1];
        lastStats.extent[2] = ext[2];
        lastStats.maxRadius = maxR;
        lastStats.cellSizeTop = params.cellSize[L-1];
        lastStats.numPoints = (numMeshes > 0) ? packed.statesOffsets[numMeshes] : 0;
    }

    void runAssignCells() {
        if (numFaces == 0 || !assignCellsPSO) return;
        MetalGlobalContext::setBuffer(centroid, 0);
        MetalGlobalContext::setBuffer(radius,   1);
        MetalGlobalContext::setBuffer(faceExclude, 2);
        MetalGlobalContext::setBytes(params,    3);
        MetalGlobalContext::setBuffer(entries,  4);
        MetalGlobalContext::dispatchThreads(assignCellsPSO, numFaces);
    }

    void runRadixSort() {
        if (numFaces == 0) return;
        sorter.sort(entries);
    }

    Index findNumValid() {
        Index n = entries.size;
        if (n == 0) return 0;
        if (entries[n - 1].cellID != 0xFFFFFFFFu) return n;
        if (entries[0].cellID == 0xFFFFFFFFu)     return 0;
        Index lo = 0, hi = n;
        while (lo < hi) {
            Index mid = lo + (hi - lo) / 2;
            if (entries[mid].cellID == 0xFFFFFFFFu) hi = mid;
            else                                    lo = mid + 1;
        }
        return lo;
    }


    void runBroadPhase(PR margin, bool enableSelfCollisions) {
        if (numFaces == 0 || !broadPhasePSO) return;
        auto& packed    = Scene<METAL, PR>::packedMeshData;
        auto& packedCol = Scene<METAL, PR>::packedCollisionData;
        MLBroadParamsHost bp{};
        bp.numFaces             = (uint32_t)numFaces;
        bp.numValid             = (uint32_t)numValidEntries;
        bp.maxNumCollisions     = (uint32_t)packedCol.maxNumCollisions;
        bp.enableSelfCollisions = enableSelfCollisions ? 1u : 0u;
        bp.numLevels            = params.numLevels;   // dynamic active level count
        bp.epsilon              = (float)margin;
        MetalGlobalContext::setBuffer(entries,                      0);
        MetalGlobalContext::setBytes(params,                        1);  // MLParams grid
        MetalGlobalContext::setBuffer(faceObj,                      2);
        MetalGlobalContext::setBuffer(packed.facets,                3);
        MetalGlobalContext::setBuffer(packed.facetsOffsets,         4);
        MetalGlobalContext::setBuffer(centroid,                     5);
        MetalGlobalContext::setBuffer(radius,                       6);
        MetalGlobalContext::setBuffer(meshBehaviors,                7);
        MetalGlobalContext::setBuffer(meshShapes,                   8);
        MetalGlobalContext::setBytes(bp,                            9);
        MetalGlobalContext::setBuffer(packedCol.numBroadCollisions, 10);
        MetalGlobalContext::setBuffer(packedCol.broadCollisions,    11);
        MetalGlobalContext::dispatchThreads(broadPhasePSO, numFaces);
    }

    void refit() { /* grid rebuilt each detectCollisions(); mirror BVH surface */ }
    void enlargeTrajectory(PR /*dt*/) { /* CCD swept BVs out of scope */ }
    void queryBegin() {
        Scene<METAL, PR>::packedCollisionData.numBroadCollisions[0] = 0;
    }

    void detectCollisions(PR margin, bool enableSelfCollisions = true) {
        using Clock = std::chrono::steady_clock;
        auto run = [&](const char* name, auto&& fn, double& dst) {
            auto a = Clock::now();
            fn();
            auto b = Clock::now();
            dst = std::chrono::duration<double, std::milli>(b - a).count();
            if (profiler) profiler->addSample(std::string(name), dst);
        };
        auto t0 = Clock::now();
        queryBegin();

        run("mlsh_buildBV", [&]{ runBuildBV(); }, lastStats.ms_buildBV);
        run("mlsh_reduce",  [&]{
            runReduceMaxRadius();
            MetalGlobalContext::commitAndWait();
        }, lastStats.ms_reduce);
        run("mlsh_grid",    [&]{ computeGrid(margin); }, lastStats.ms_grid);
        run("mlsh_assign",  [&]{ runAssignCells(); }, lastStats.ms_assign);
        run("mlsh_sort",    [&]{
            runRadixSort();
            MetalGlobalContext::commitAndWait();
            numValidEntries = findNumValid();
        }, lastStats.ms_sort);
        // Home-only insertion + cross-level query walk: no cell-property /
        // pair-prefix passes (and their two host syncs) — the per-face broad
        // phase binary-searches the sorted entries directly.
        lastStats.ms_cellprop   = 0.0;
        lastStats.ms_pairprefix = 0.0;
        numCells = 0; numCandidatePairs = 0;
        run("mlsh_broad",   [&]{
            runBroadPhase(margin, enableSelfCollisions);
            if (verbose) MetalGlobalContext::commitAndWait();
        }, lastStats.ms_broad);

        auto t1 = Clock::now();
        lastStats.ms_total          = std::chrono::duration<double, std::milli>(t1 - t0).count();
        lastStats.numFaces          = numFaces;
        lastStats.numValidEntries   = numValidEntries;
        lastStats.numCells          = numCells;
        lastStats.numCandidatePairs = numCandidatePairs;
        lastStats.numExcluded       = numExcludedFaces;
        lastStats.numLevels         = effectiveLevels();
        if (verbose) {
            lastStats.numBroadOut =
                Scene<METAL, PR>::packedCollisionData.numBroadCollisions[0];
        }
    }

    void printLastStats(std::ostream& os, Index frame, Index substep) const {
        os << "[F=" << frame << " S=" << substep << "] mlsh:"
           << " L=" << lastStats.numLevels
           << " faces=" << lastStats.numFaces
           << " excl=" << lastStats.numExcluded
           << " valid=" << lastStats.numValidEntries
           << " cells=" << lastStats.numCells
           << " pairs=" << lastStats.numCandidatePairs
           << " broadOut=" << lastStats.numBroadOut
           << " maxR=" << lastStats.maxRadius
           << " cellTop=" << lastStats.cellSizeTop
           << " ext=" << lastStats.extent[0] << "x" << lastStats.extent[1]
           << "x" << lastStats.extent[2]
           << " | bv=" << lastStats.ms_buildBV
           << " red=" << lastStats.ms_reduce
           << " grid=" << lastStats.ms_grid
           << " asgn=" << lastStats.ms_assign
           << " srt=" << lastStats.ms_sort
           << " cell=" << lastStats.ms_cellprop
           << " pp=" << lastStats.ms_pairprefix
           << " brd=" << lastStats.ms_broad
           << " tot=" << lastStats.ms_total << "ms\n";
    }

    void queryEnd() {
        MetalGlobalContext::commitAndWait();
        auto& packedCol = Scene<METAL, PR>::packedCollisionData;
        if (packedCol.numBroadCollisions[0] > packedCol.maxNumCollisions) {
            std::cout << "[MLSH] broad-phase overflow: "
                      << packedCol.numBroadCollisions[0]
                      << "/" << packedCol.maxNumCollisions << "\n";
        }
    }

    void showBox()      {}
    void showSceneBox() {}
    void queryClickRay(const Ray& /*ray*/) {}
};


